INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(6, 'plPL', 'Nagroda za Garricka Cichostopego', 'Garrick Cichostopy – rzezimieszek, który od tygodni nęka naszych rolników i kupców – był widziany w szopie przy winnicach, na wschód od opactwa, za mostem. Przynieś mi głowę tego łotra i zgarnij nagrodę!$B$BAle uważaj, $N. Garrick zebrał wokół siebie bandę zbirów. Niełatwo będzie się do niego dostać.', 'Zabij Garricka Cichostopego i przynieś jego głowę zastępcy Willemowi w Opactwie Północnych Włości.', '', 'Wróć do zastępcy Willema w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(7, 'plPL', 'Porządki w obozie koboldów', 'Twoje pierwsze zadanie polega na oczyszczeniu terenu, $N. Klan koboldów zagnieździł się w lasach na północy. Udaj się tam i walcz z koboldzimi szkodnikami, które napotkasz. Przetrzeb ich szeregi, abyśmy pewnego dnia mogli wypędzić ich z Północnych Włości.', 'Zabij 8 koboldzich szkodników, a następnie wróć do marszałka McBride\'a.', '', 'Wróć do marszałka McBride\'a w Opactwie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(11, 'plPL', 'Nagroda za gnole z Wodnołapych', 'Gnole – brutalne stwory, które nie mają czego szukać na tych ziemiach – widziano wzdłuż granic Kniei Elwynn. Duża sfora, znacznie większa, niż jesteśmy w stanie sami pokonać, zagnieździła się w lesie na południe od tamtej wieży strażniczej. Inna grupa opanowała okolice Jeziora Kamiennego Kopca na wschodzie.$B$BArmia Wichrogrodu wyróżni każdego, kto pomoże je wybić. Przynieś mi ich malowane opaski jako dowód twojego czynu.', 'Przynieś 8 malowanych opasek gnoli zastępcy Rainerowi w koszarach.', '', 'Wróć do zastępcy Rainera na Skraju Lasu w Kniei Elwynn.', '', '', '', '', 0),
(15, 'plPL', 'Zbadaj Echową Grań', '$N, moi zwiadowcy donoszą, że plaga koboldów jest większa, niż sądziliśmy. Grupa koboldzich robotników rozbiła obóz w pobliżu Kopalni Echowej Grani na północy.$B$BIdź do kopalni i pozbądź się ich. Wiemy, że jest ich co najmniej ośmiu. Zabij ich, sprawdź, czy nie ma ich więcej, a potem złóż mi raport.', 'Zabij 8 koboldzich robotników, a następnie złóż raport marszałkowi McBride\'owi.', '', 'Wróć do marszałka McBride\'a w Opactwie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(16, 'plPL', 'Daj Gerardowi się napić', '', '', '', 'Wróć do Gerarda Tillera w Kniei Zmierzchu.', '', '', '', '', 0),
(18, 'plPL', 'Bractwo złodziei', 'Od niedawna po Północnych Włościach kręci się nowa banda złodziei. Nazywają siebie Bractwem Nieskornych i widziano ich za rzeką, na wschodzie.$B$BNie wiem, co knują, ale na pewno nic dobrego! Przynieś mi chusty, które noszą, a nagrodzę cię bronią.', 'Przynieś 8 czerwonych jutowych chust zastępcy Willemowi przed Opactwem Północnych Włości.', '', 'Wróć do zastępcy Willema w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(21, 'plPL', 'Potyczka na Echowej Grani', 'Twoje wcześniejsze zwiady dowodzą, że Kopalnię Echowej Grani trzeba oczyścić. Wróć do kopalni i pomóż wykurzyć z niej koboldy.$B$BNie trać czasu, $N. Im dłużej koboldy będą bezkarnie siedzieć w kopalni, tym mocniej zakorzenią się w Północnych Włościach.', 'Zabij 8 koboldzich wyrobników, a następnie wróć do marszałka McBride\'a w Opactwie Północnych Włości.', '', 'Wróć do marszałka McBride\'a w Opactwie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(33, 'plPL', 'Wilki u granic', 'Cokolwiek dręczy te wilki, nie ustępuje. Z każdym dniem chorych wilków przybywa. Z bólem proszę kogokolwiek o zabijanie zwierząt, ale musimy zniszczyć chore młode wilki, zanim ta niewielka zaraza zamieni się w epidemię.$B$BZabij chore młode wilki w dolinie i przynieś mi ich chore wilcze skóry jako dowód twojego czynu.$B', 'Przynieś 8 chorych wilczych skór Eaganowi Skórołupowi przed Opactwem Północnych Włości.', '', 'Wróć do Eagana Skórołupa w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(35, 'plPL', 'Kolejne niepokoje', 'Jeśli obawiasz się, że plotki o murlokach są prawdziwe, zrób tak: udaj się na wschodni most w Elwynn i porozmawiaj ze strażnikiem Thomasem. Od tygodnia stacjonuje przy moście i będzie wiedział, jak wygląda sytuacja w okolicy.$B$BPrzynieś mi jego raport.', 'Marszałek Dughan chce, żebyś $gporozmawiał:porozmawiała; ze strażnikiem Thomasem.', '', '', '', '', '', '', 0),
(37, 'plPL', 'Odnajdź zaginionych strażników', 'Kilka dni temu wysłaliśmy dwóch strażników, Rolfa i Malakaia, żeby zbadali brzeg rzeki, i jeszcze nie wrócili. Żeby dokończyć raport, muszę wiedzieć, co się z nimi stało.$B$BIdź w górę rzeki na północ i odnajdź strażników... albo to, co z nich zostało.', 'Strażnik Thomas chce, żebyś $gposzedł:poszła; w górę rzeki na północ i $godszukał:odszukała; dwóch zaginionych strażników, Rolfa i Malakaia.', '', '', '', '', '', '', 0),
(39, 'plPL', 'Dostarcz raport Thomasa', 'Powiedz marszałkowi Dughanowi o śmierci Malakaia i Rolfa i zamelduj mu, że obecne siły nie są w stanie powstrzymać murloków we wschodnim Elwynn.$B$BWiem, że nie mamy wielu wolnych żołnierzy, ale może Dughan kogoś znajdzie.', 'Zamelduj się u marszałka Dughana w Złotych Włościach.', '', '', '', '', '', '', 0),
(40, 'plPL', 'Rybie zagrożenie', '$N, w Kniei Elwynn pojawiło się nowe zagrożenie! Murloki płyną w górę strumieni wschodniego Elwynn, płoszą ryby i napadają na spokojnych ludzi!$B$BOstrzegłem marszałka Dughana, ale on bardziej martwi się gnolami i bandytami. Nie jest przekonany, że murloki stanowią zagrożenie.$B$BProszę, $N, porozmawiaj z Dughanem i przekonaj go, żeby wysłał więcej żołnierzy na wschód!', 'Remy „Dwa Razy” chce, żebyś $gporozmawiał:porozmawiała; z marszałkiem Dughanem w Złotych Włościach.', '', '', '', '', '', '', 0),
(45, 'plPL', 'Odkryj los Rolfa', 'Po dokładniejszym przeszukaniu okolicy znajdujesz ślady płetwiastych stóp prowadzące na wschód wzdłuż brzegu Jeziora Kamiennego Kopca. W oddali na wschodzie ledwie widać wioskę murloków.$B$BByć może tam dopełnił się los Rolfa...', 'Przeszukaj wioskę murloków w poszukiwaniu Rolfa lub śladów jego śmierci.', '', '', '', '', '', '', 0),
(46, 'plPL', 'Nagroda za murloki', 'Armia Wichrogrodu wyznaczyła nagrodę za czyhające murloki i murloki zbieracze w Elwynn. Wyrżnij je i przynieś mi ich rozdarte płetwy, a Armia Wichrogrodu sowicie cię wynagrodzi.$B$BMurloki zbudowały wioskę nad Jeziorem Kamiennego Kopca na północ stąd i drugą na południu, tam gdzie rozwidla się strumień.', 'Przynieś 8 rozdartych płetw murloków strażnikowi Thomasowi przy wschodnim moście w Elwynn.', '', 'Wróć do strażnika Thomasa w Kniei Elwynn.', '', '', '', '', 0),
(47, 'plPL', 'Wymiana złotego pyłu', 'Koboldy w tych stronach czasem noszą przy sobie złoty pył. Bardzo by mi się przydał – przynieś mi go trochę, a dam ci najlepszą cenę w mieście... najlepszą cenę w mieście!$B$BKoboldy znajdziesz w Kopalni Dalekiej Głębi na południu i w okolicy Kopalni Jaspisowej Żyły na północnym wschodzie.', 'Przynieś 10 porcji złotego pyłu Remy\'emu „Dwa Razy” w Złotych Włościach. Złoty pył można zdobyć od koboldów w Kniei Elwynn.', '', 'Wróć do Remy\'ego „Dwa Razy” w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(52, 'plPL', 'Chroń pogranicze', 'Witaj, $N. Im dalej od Złotych Włości, tym dzikie zwierzęta stają się coraz agresywniejsze, a obóz drwali we Wschodniej Dolinie jest niemal bez przerwy atakowany przez wilki i niedźwiedzie!$B$BPrzydałaby się nam tu twoja pomoc.', 'Zabij 8 drapieżców i 5 młodych leśnych niedźwiedzi, a następnie wróć do strażnika Thomasa przy wschodnim moście w Elwynn.', '', 'Wróć do strażnika Thomasa w Kniei Elwynn.', '', '', '', '', 0),
(54, 'plPL', 'Zgłoś się w Złotych Włościach', '$N, jako $c $gwykazałeś:wykazałaś; się troską o bezpieczeństwo Północnych Włości. Teraz powierzam ci ochronę okolicznej Kniei Elwynn.$B$BJeśli przyjmujesz to zadanie, mam przygotowane dokumenty, które trzeba dostarczyć marszałkowi Dughanowi w Złotych Włościach. Złote Włości leżą przy drodze na południe, za bramami granicznymi.', 'Zanieś dokumenty marszałka McBride\'a marszałkowi Dughanowi w Złotych Włościach.', '', '', '', '', '', '', 0),
(59, 'plPL', 'Zbroja z płótna i skóry', 'W nagrodę za spryt i męstwo mam tu znacznik, który można wymienić na jedną część zbroi. Zanieś go Sarze Timberlain do obozu drwali we Wschodniej Dolinie. Daj jej znacznik, a ona przygotuje dla ciebie zbroję. A kiedy ją dostaniesz, $N, użyj jej w obronie Elwynn.$B$BObóz drwali we Wschodniej Dolinie leży za posterunkiem strażnika Thomasa, na wschodzie.', 'Oddaj Sarze Timberlain znacznik zbroi Wichrogrodu.', '', '', '', '', '', '', 0),
(60, 'plPL', 'Koboldzie świece', 'Witaj, $gszanowny panie:szanowna pani;! Masz chwilę?$B$BRazem z bratem prowadzimy aptekę w Wichrogrodzie, a ja przyjechałem tu zebrać duże świece dla ich wosku. Pomożesz mi?$B$BDuże świece można zdobyć od koboldów, a słyszałem plotki, że koboldy zagnieździły się w kopalniach Elwynn... w Kopalni Dalekiej Głębi na południu i w Kopalni Jaspisowej Żyły na wschodzie. Radzę szukać świec w jednym z tych miejsc.', 'Przynieś 8 dużych świec Williamowi Pestle\'owi w Złotych Włościach.', '', 'Wróć do Williama Pestle\'a w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(61, 'plPL', 'Dostawa do Wichrogrodu', 'Mój brat Morgan czeka w Wichrogrodzie na dostawę świec. Nie mam czasu, żeby samemu tam jechać, ale jeśli zechcesz zanieść mu przesyłkę, dobrze ci zapłaci.$B$BŚwiece już zapakowałem, a Morgana znajdziesz w naszym sklepie, Aptece Pestle\'a, w Dzielnicy Handlowej Wichrogrodu.', 'Zanieś przesyłkę Williama Morganowi Pestle\'owi w Dzielnicy Handlowej Wichrogrodu.', '', '', '', '', '', '', 0),
(62, 'plPL', 'Kopalnia Dalekiej Głębi', 'Nie tylko kopalnia w Północnych Włościach ma kłopoty! Dostaję raporty, że Kopalnia Dalekiej Głębi w Elwynn również stała się schronieniem dla koboldów.$B$BZbadaj kopalnię, potwierdź te doniesienia, a potem wróć do mnie. Kopalnia leży niemal dokładnie na południe od Złotych Włości, między zagrodami Stonefieldów i Maclure\'ów.', 'Zbadaj Kopalnię Dalekiej Głębi, a następnie wróć do marszałka Dughana w Złotych Włościach.', 'Przeprowadź zwiad w Kopalni Dalekiej Głębi', 'Wróć do marszałka Dughana w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(67, 'plPL', 'Legenda o Stalvanie', 'Stalvan, co? Sprawdzę w miejskim rejestrze.$b$bStalvan... Stalvan... zobaczmy. O, jest! Mam wpis o panu Stalvanie Mgłopłaszczu. Ostatni odnotowany adres to szkoła w Księżycowym Potoku. Ojej, cóż za nieaktualne dane!$b$bZrobisz mi przysługę, $gprzyjacielu:przyjaciółko;? Jeśli będziesz w Księżycowym Potoku, daj mi znać, czy dowiesz się czegoś nowego o tym jegomościu. Lubię mieć porządek w rejestrach.', 'Udaj się do szkoły w Księżycowym Potoku i przynieś urzędnikowi Daltry\'emu wszelkie nowe informacje o Stalvanie.', '', '', '', '', '', '', 0),
(68, 'plPL', 'Legenda o Stalvanie', 'W starym kufrze znajdujesz zakurzony niewysłany list.', 'Zanieś zakurzony niewysłany list urzędnikowi Daltry\'emu.', '', '', '', '', '', '', 0),
(69, 'plPL', 'Legenda o Stalvanie', 'O rety! Musiałem to przeoczyć za pierwszym razem. W rejestrze, tuż pod pierwszym adresem Stalvana, jest wpisany jeszcze jeden, tylko częściowo wydrapany. Wygląda na to, że udawał się do karczmy „Lwia Duma” w Złotych Włościach. Warto tam zajrzeć, $N.', 'Udaj się do karczmy „Lwia Duma” i sprawdź, czy ktoś tam słyszał o Stalvanie.', '', '', '', '', '', '', 0),
(70, 'plPL', 'Legenda o Stalvanie', 'Imię Stalvan coś mi mówi. Już pamiętam.$b$bWiele lat temu, w burzową noc, przybył tu posłaniec, szukając schronienia na noc. Tuż przed północą ten człowiek zbiegł po schodach z krzykiem, z twarzą bladą ze strachu. Wciąż w nocnej koszuli zniknął w ulewie.$b$bW pośpiechu zostawił swoje listy w skrzyni na górze. Nigdy po nie nie wrócił. Został jeden od tego Stalvana, zaadresowany do Dzielnicy Kanałów w Wichrogrodzie. Weź go sobie.', 'Wyjmij ze skrzyni niedostarczony list Stalvana i dostarcz go do Dzielnicy Kanałów w Wichrogrodzie.', '', 'Porozmawiaj z dozorcą Folsomem w Wichrogrodzie.', '', '', '', '', 0),
(71, 'plPL', 'Raport dla Thomasa', 'Teraz, gdy masz oba medaliony, zanieś je strażnikowi Thomasowi przy moście, żeby poznał los swoich zamordowanych strażników.', 'Dostarcz medaliony Rolfa i Malakaia strażnikowi Thomasowi przy wschodnim moście w Elwynn.', '', '', '', '', '', '', 0),
(72, 'plPL', 'Legenda o Stalvanie', 'Mój ojciec był dozorcą tej posiadłości na długo przede mną. To on musiał zmywać krew po masakrze. Ale mniejsza z tym.$b$bOstatnie środki z funduszu powierniczego Flintridge\'ów się wyczerpały. Teraz resztki rodzinnego dobytku pójdą pod młotek. Podziękuj sępom od podatków. Jeśli naprawdę tak cię korci, żeby dowiedzieć się czegoś więcej, możesz przejrzeć te graty. Kto wie, co znajdziesz.', 'Przeszukaj spakowany dobytek w poszukiwaniu jakiejś wskazówki.', '', '', '', '', '', '', 0),
(74, 'plPL', 'Legenda o Stalvanie', 'W skrzyni znajdujesz różne przedmioty: zatęchłe pamiątki rodzinne, portret rodzinny, kilka myśliwskich trofeów i parę starych ksiąg. Przy samym dnie, pod ceramicznym wazonem, odkrywasz podartą stronę dziennika.', 'Podarta strona dziennika, którą $gznalazłeś:znalazłaś;, jest twoją następną wskazówką.', '', '', '', '', '', '', 0),
(75, 'plPL', 'Legenda o Stalvanie', 'Kiedy się tu wprowadziłem, w skrzyni na górze leżał plik pergaminów. Przejrzałem je raz, zaraz po przybyciu, ale dałem sobie spokój, kiedy mgła zasnuła mi ślepia.$b$bZrób przysługę staremu, niemal ślepemu człowiekowi i sprawdź skrzynię na górze – może znajdziesz coś, co pomoże ci dowiedzieć się więcej o tym całym Stalvanie. Jestem prawie pewien, że jest tam wyblakła strona dziennika, która może cię zainteresować. Przynieś mi ją, a pomogę, jak tylko zdołam.', 'Marszałek Haggard chce, żebyś $gsprawdził:sprawdziła;, czy w skrzyni na górze jest wyblakła strona dziennika.', '', 'Wróć do marszałka Haggarda w obozie drwali we Wschodniej Dolinie w Kniei Elwynn.', '', '', '', '', 0),
(76, 'plPL', 'Kopalnia Jaspisowej Żyły', 'Dzięki tobie wiemy, że w Kopalni Dalekiej Głębi roi się od koboldów. Teraz potrzebujemy zwiadowcy, który zbada położoną dalej Kopalnię Jaspisowej Żyły.$B$BZbadaj Kopalnię Jaspisowej Żyły i potwierdź, czy są tam koboldy. Żeby do niej dotrzeć, idź drogą na wschód aż do Wieży Azory. Od wieży skręć na północ, a znajdziesz kopalnię u podnóża wzgórz.', 'Zbadaj Kopalnię Jaspisowej Żyły, a następnie złóż raport marszałkowi Dughanowi w Złotych Włościach.', 'Przeprowadź zwiad w Kopalni Jaspisowej Żyły', 'Wróć do marszałka Dughana w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(78, 'plPL', 'Legenda o Stalvanie', 'Znam kogoś, kto może ci pomóc. Kiedy dowodziłem strażą Wichrogrodu, chadzaliśmy na drinka do tawerny „Szkarłatny Kruk” w Mrocznych Włościach. Tamtejszy szynkarz, Smitts, był prawdziwym znawcą miejscowych opowieści. Pokaż mu tę stronę i zobacz, co o niej powie.', 'Zanieś wyblakłą stronę dziennika szynkarzowi Smittsowi w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', '', '', 0),
(83, 'plPL', 'Wyroby z czerwonego lnu', 'Banda Nieskornych w Północnych Włościach nosi maski z juty, ale Nieskorni w Elwynn noszą lniane, z których mogę uszyć porządne lniane wyroby.$B$BPrzynieś mi czerwone lniane chusty, a uszyję z nich coś dla ciebie.$B$BCzłonkowie bandy Nieskornych mają obozy porozrzucane po całym Elwynn.', 'Przynieś 6 czerwonych lnianych chust Sarze Timberlain do obozu drwali we Wschodniej Dolinie.', '', 'Wróć do Sary Timberlain w obozie drwali we Wschodniej Dolinie w Kniei Elwynn.', '', '', '', '', 0),
(84, 'plPL', 'Z powrotem do Billy\'ego', 'Proszę bardzo. A kiedy dasz ten placek temu Billy\'emu, powiedz mu, że mam nadzieję, że się nim udławi!', 'Zanieś placek z boczkiem Billy\'emu Maclure\'owi w winnicach Maclure\'ów.', '', '', '', '', '', '', 0),
(85, 'plPL', 'Zgubiony naszyjnik', 'Zgubiłam naszyjnik i myślę, że zabrał go ten łobuz Billy Maclure! Zwykle kręci się jak szczur po winnicach Maclure\'ów na wschód stąd.$B$BOdzyskaj dla mnie naszyjnik, a ogrzejesz serce starej wdowy.', 'Porozmawiaj z Billym Maclure\'em.', '', '', '', '', '', '', 0),
(86, 'plPL', 'Placek dla Billy\'ego', 'Może gdybym dostał placek, powiedziałbym ci, kto ma ten naszyjnik. A wiesz, myślę, że ta stara Bernice z tamtej farmy piecze świetne placki z boczkiem...$B$BMoże gdybyś $gdał:dała; jej trochę dziczyzny z dzików, które kręcą się koło naszych farm, i $gpowiedział:powiedziała;, na co to, upiekłaby dla ciebie placek.', 'Przynieś 4 kawały dziczyzny „Cioci” Bernice Stonefield na farmę Stonefieldów.', '', 'Wróć do „Cioci” Bernice Stonefield na farmie Stonefieldów w Kniei Elwynn.', '', '', '', '', 0),
(87, 'plPL', 'Złotozęby', 'Bawiłem się koło Kopalni Dalekiej Głębi i chyba upuściłem, eee... to znaczy widziałem naszyjnik tej starszej pani. Nie pytaj, skąd się tam wziął... to nie ja!$B$BW każdym razie widziałem, jak wielki kobold ze złotym zębem podnosi naszyjnik i ucieka z nim do kopalni. Znajdź tego kobolda, a znajdziesz naszyjnik, przysięgam!', 'Zanieś naszyjnik Bernice „Cioci” Bernice Stonefield na farmę Stonefieldów.', '', 'Wróć do „Cioci” Bernice Stonefield na farmie Stonefieldów w Kniei Elwynn.', '', '', '', '', 0),
(88, 'plPL', 'Księżniczka musi zginąć!', 'Brackwellowie mają nagradzaną świnię, Księżniczkę. Ta locha jest OGROMNA, a utyła tak, bo zakradała się tutaj i zjadała moje warzywa!$B$BWięc zanim znowu przyjdzie na nasze pola... Księżniczka musi zginąć! Przynieś mi jej obrożę na dowód, a dam ci coś za fatygę!$B$BKsiężniczka zwykle przebywa na dyniowym polu Brackwellów, na wschód stąd, za farmą Maclure\'ów. Dopadnij ją, zanim zgłodnieje i wróci tutaj!', 'Zabij Księżniczkę, zabierz jej obrożę i zanieś ją Mamie Stonefield na farmę Stonefieldów.', '', 'Wróć do Mamy Stonefield na farmie Stonefieldów w Kniei Elwynn.', '', '', '', '', 0),
(94, 'plPL', 'Czujne oko', 'Mój rywal, Morganth, to okrutny mag o wielkiej mocy, który mieszka w Wieży Ilgalara w Górach Rudej Grani. Opracowałem sposób, by go szpiegować – Oko Azory – i teraz mogę obserwować go z daleka.$B$BAle żeby zgłębić jego myśli... potrzebuję dodatkowej pomocy.$B$BJeśli chcesz, zanieś mój Glif Azory do Wieży Ilgalara. Umieść go na posągu lwa w pobliżu wieży.$B$BGdy to zrobisz, moc Azory ukaże mi wizje przyszłych planów Morgantha.', 'Zanieś Glif Azory do posągu lwa w pobliżu Wieży Ilgalara w Górach Rudej Grani.', '', '', '', '', '', '', 0),
(106, 'plPL', 'Młodzi kochankowie', 'Och, jestem przeklęta! Moje serce należy do Tommy\'ego Joe Stonefielda, ale nasze rodziny są zaciekłymi wrogami. Nie mogę się z nim widywać, choć oczy bolą mnie z tęsknoty za jego przystojną twarzą!$B$BProszę, weź ten list i daj go Tommy\'emu Joe. Zwykle przesiaduje nad rzeką na zachód od farmy Stonefieldów, która leży dokładnie na zachód stąd.', 'Daj list miłosny Maybell Tommy\'emu Joe Stonefieldowi.', '', '', '', '', '', '', 0),
(107, 'plPL', 'Liścik do Williama', 'Założę się, że William Pestle ma miksturę, która połączy naszych młodych kochanków!$B$BProszę, zanieś ten liścik Williamowi. Zatrzymał się w karczmie „Lwia Duma” w Złotych Włościach.', 'Zanieś liścik babci Stonefield Williamowi Pestle\'owi.', '', '', '', '', '', '', 0),
(109, 'plPL', 'Zgłoś się do Gryana Mocnopłaszcza', 'Wygląda na to, że $gstoczyłeś:stoczyłaś; w swoim życiu sporo walk. Jeśli jeszcze tego nie $gzrobiłeś:zrobiłaś;, zgłoś się do Gryana Mocnopłaszcza. Stoi na czele Milicji Ludowej, która chroni pola uprawne Zachodniego Skraju. Założę się, że przyda mu się twoja pomoc. Zwykle można go znaleźć w kamiennej wieży na Wzgórzu Strażniczym, tuż przy drodze w środku Zachodniego Skraju.', 'Porozmawiaj z Gryanem Mocnopłaszczem. Zwykle można go znaleźć w kamiennej wieży na Wzgórzu Strażniczym, tuż przy drodze, w środku Zachodniego Skraju.', '', '', '', '', '', '', 0),
(111, 'plPL', 'Porozmawiaj z babcią', 'Proszę, $N, porozmawiaj z moją babcią. Jeśli ktokolwiek potrafi znaleźć sposób, żebym był z Maybell, to właśnie ona.$B$BJest w naszym domu na wschód stąd.', 'Porozmawiaj z babcią Stonefield.', '', '', '', '', '', '', 0),
(112, 'plPL', 'Zbieranie wodorostów', 'Mogę zrobić dla Maybell trunek niewidzialności, żeby wymknęła się z winnic Maclure\'ów i poszła do Tommy\'ego Joe. Ale żeby go przyrządzić, potrzebuję kryształowych wodorostów.$B$BChoć wodorosty zwykle rosną w oceanie... murloki czasem je zbierają. Sprawdź, czy murloki przy Kryształowym Jeziorze jakieś mają. Kryształowe Jezioro leży tuż na wschód od Złotych Włości.', 'Przynieś 4 liście kryształowego wodorostu Williamowi Pestle\'owi w Złotych Włościach.', '', 'Wróć do Williama Pestle\'a w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(114, 'plPL', 'Ucieczka', 'Zanieś ten trunek niewidzialności młodej Maybell. Powinien działać wystarczająco długo, żeby mogła odwiedzić Tommy\'ego Joe.', 'Zanieś trunek niewidzialności Maybell Maclure.', '', '', '', '', '', '', 0),
(118, 'plPL', 'Cena podków', 'Zużywam tyle żelaza na wyposażenie straży Wichrogrodu, że nie starcza mi na podkowy dla koni ze stajni!$B$BZanieś ten liścik kowalowi Argusowi w Złotych Włościach. Wyjaśniam w nim swój kłopot i proszę o dostawę podków.', 'Zanieś liścik Vernera kowalowi Argusowi w Złotych Włościach w Kniei Elwynn.', '', '', '', '', '', '', 0),
(119, 'plPL', 'Powrót do Vernera', 'Dobra, dam mu te jego 50 podków...$B$BOto one, zapakowane i gotowe do drogi! Powiedz Vernerowi, że miło robić z nim interesy, i dopilnuj, żeby przeczytał liścik przyczepiony do skrzynki!', 'Wróć do Vernera Osgooda w Jeziernych Włościach w Górach Rudej Grani. Oddaj mu skrzynkę podków.', '', '', '', '', '', '', 0),
(123, 'plPL', 'Kolekcjoner', 'Ten liścik to harmonogram z listą dni i godzin, w których pewna osoba – opisana jedynie jako „Kolekcjoner” – ma odbierać dostawy złota z kopalń w Kniei Elwynn.$B$BZ harmonogramu wynika, że Kolekcjoner przebywa w pobliżu dyniowego pola Brackwellów we wschodnim Elwynn.$B$BTo brzmi poważnie. $GPowinieneś:Powinnaś; zgłosić to marszałkowi Dughanowi w Złotych Włościach.', 'Udaj się do marszałka Dughana w Złotych Włościach i daj mu harmonogram Kolekcjonera.', '', '', '', '', '', '', 0),
(147, 'plPL', 'Obława', 'Jeśli „Kolekcjoner” zabiera złoto z naszych kopalń, to okrada królestwo! Postaw go przed obliczem sprawiedliwości i przynieś mi pierścień, o którym wspomina harmonogram, który mi $gdałeś:dałaś;. Może nam powiedzieć, dla kogo Kolekcjoner pracuje...$B$BZ harmonogramu wynika, że Kolekcjoner ukrywa się na dyniowym polu Brackwellów. Tam go szukaj.', 'Znajdź i zabij „Kolekcjonera”, a następnie wróć do marszałka Dughana z pierścieniem Kolekcjonera.', '', 'Wróć do marszałka Dughana w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(176, 'plPL', 'Poszukiwany: „Wyżer”', 'Poszukiwany: Wyżer$B$BOgromny gnol, Wyżer, grasuje w lasach południowo-zachodniego Elwynn. Udaremnił wszystkie próby schwytania go.$B$BArmia Wichrogrodu wyznaczyła za gnola hojną nagrodę. Aby ją otrzymać, łowcy nagród powinni dostarczyć dowód śmierci Wyżera marszałkowi Dughanowi w Złotych Włościach.', 'Zabij gnola Wyżera i zanieś jego ogromny pazur marszałkowi Dughanowi.', '', 'Wróć do marszałka Dughana w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(178, 'plPL', 'Zguba Theocritusa', '<Słyszysz bezcielesny głos...>$B$BNie lękaj się. Jestem Theocritus, arcymag Wieży Azory w Kniei Elwynn. Wisior, który trzymasz, służy do porozumiewania się gnoli z klanu Cienioskórych z ich panem, Morganthem.$B$BPo miesiącach badań doszedłem do wniosku, że ja również mogę porozumiewać się przez te wisiory. Jeśli słyszysz tę wiadomość, moje zaklęcie się powiodło.$B$BPrzynieś mi ten wisior, a wynagrodzę cię za przysługę.', 'Zanieś wyblakły wisior Cienioskórych magowi Theocritusowi do Wieży Azory w Kniei Elwynn.', '', '', '', '', '', '', 0),
(239, 'plPL', 'Garnizon Zachodniego Potoku potrzebuje pomocy!', 'Garnizon na naszej zachodniej granicy donosi o coraz większej aktywności gnoli i złodziei. Proszą o przysłanie kolejnych żołnierzy Wichrogrodu... ale po prostu nie mamy wolnych ludzi!$B$BJeśli możesz pomóc, bardzo się przydasz. Idź do Garnizonu Zachodniego Potoku, porozmawiaj z zastępcą Rainerem i dowiedz się, czego potrzebuje.$B$BGarnizon leży przy drodze na zachód. Gdy przejdziesz przez most nad strumykiem, będzie po prawej.', 'Udaj się do Garnizonu Zachodniego Potoku i porozmawiaj z zastępcą Rainerem.', '', '', '', '', '', '', 0),
(249, 'plPL', 'Morganth', 'Po długich obserwacjach odkryłem plany Morgantha.$B$BSzuka Kosy Eluny... i być może już ją znalazł! Jeśli tak, Góry Rudej Grani, a także królestwo Wichrogrodu, wkrótce poczują jego mroczną potęgę.$B$BNie jestem gotów stanąć przeciw Morganthowi, ale obawiam się, że trzeba się nim zająć już teraz. Musisz więc wejść do Wieży Ilgalara i stawić czoła Morganthowi.$B$BPokonaj go i przynieś mi jego Wisior cienia. Zrób to, a królestwo będzie ci wiele zawdzięczać.', 'Pokonaj Morgantha.$B$BZanieś jego Wisior cienia Theocritusowi do Wieży Azory w Kniei Elwynn.', '', 'Wróć do Theocritusa w Wieży Azory w Kniei Elwynn.', '', '', '', '', 0),
(344, 'plPL', 'Brat Paxton', '„Naprężenia żelaza”? Tak, znam tę księgę. Całkiem dobra, napisał ją kilkadziesiąt lat temu krasnoludzki górnik Margulf Blaggon. Większość życia spędził głęboko w górach Khaz Modan, wydobywając rudę. Mądry gość!$B$BAle o czym to ja...? A tak, „Naprężenia żelaza”! Obawiam się, że księgę przeniesiono do Opactwa Północnych Włości. Opiekun biblioteki opactwa, brat Paxton, chciał zrobić jej odpis na własne półki.$B$BAle to było przed wieloma miesiącami. Ciekawe, czemu zajmuje mu to tyle czasu...', 'Porozmawiaj z bratem Paxtonem w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(345, 'plPL', 'Zapasy atramentu', 'Od dawna zamierzam dokończyć swój odpis „Naprężeń żelaza”, ale...$B$BWidzisz, do przepisywanych ksiąg robię własny atrament. To mój własny przepis: nie rozmazuje się, nie spływa i schnie bardzo szybko. Niestety, schnie za szybko! Ostatnia porcja wyschła, zanim skończyłem przepisywanie, a nie miałem okazji zrobić nowej!$B$BŻeby zrobić więcej, potrzebuję rudy żelaza z Rethbanu z Gór Rudej Grani. Zwykle dostarcza mi ją brygadzista Oslow z Jeziernych Włości.', 'Porozmawiaj z brygadzistą Oslowem w Jeziernych Włościach i poproś go o rudę żelaza z Rethbanu.', '', '', '', '', '', '', 0),
(346, 'plPL', 'Powrót do Kristoffa', 'Skoro skończyłem przepisywać księgę, oto oryginał „Naprężeń żelaza”. Dziękuję za cierpliwość, a jeśli spotkasz Miltona, przekaż mu, proszę, że przepraszam za tak długą zwłokę.', 'Wróć do brata Kristoffa na Placu Katedralnym. Oddaj mu księgę „Naprężenia żelaza”.', '', '', '', '', '', '', 0),
(347, 'plPL', 'Ruda z Rethbanu', 'Ruda z Rethbanu nosi imię człowieka, który pierwszy ją znalazł, Barta Rethbana. Po wytopieniu nie jest tak mocna jak żelazo, ale ma ciemną, matową barwę, której niektórzy skrybowie używają do barwników. Można ją znaleźć w Jaskiniach Rethbanu, na północ stąd.$B$BZwykle mamy jej trochę w zapasie, ale jesteśmy zbyt zajęci przygotowaniami do napaści orków, żeby ją wydobywać. Poza tym... w Jaskiniach Rethbanu zamieszkały gnole z Rudej Grani, a ich harownicy sami wydobywają rudę.$B$BWięc jeśli jej potrzebujesz, musisz ją zdobyć $gsam:sama;.', 'Zbierz 5 porcji rudy z Rethbanu i zanieś ją bratu Paxtonowi do biblioteki w Północnych Włościach.', '', 'Wróć do brata Paxtona w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(511, 'plPL', 'Zaszyfrowany list', 'Jeden z listów na tym stole jest zaszyfrowany i nie sposób go odczytać.', 'Zanieś zaszyfrowany list mistrzowi wiedzy Dibbsowi w Południowym Brzegu.', '', '', '', '', '', '', 0),
(783, 'plPL', 'Zagrożenie od wewnątrz', 'Mam nadzieję, że mocno $gzapiąłeś:zapięłaś; pas, bo w Północnych Włościach jest robota nawet dla kogoś tak $gmłodego:młodej; jak ty.$B$BI nie mam na myśli pracy w polu.$B$BStraż Wichrogrodu ledwo daje radę utrzymać tu spokój – tak wielu z nas walczy w dalekich krainach, a tak wiele zagrożeń czai się tuż obok. Dlatego prosimy o pomoc każdego, kto chce bronić swojego domu. I swojego Przymierza.$B$BJeśli $gprzybyłeś:przybyłaś;, by odpowiedzieć na wezwanie, porozmawiaj z moim przełożonym, marszałkiem McBride\'em. Jest w opactwie za mną.', 'Porozmawiaj z marszałkiem McBride\'em.', '', '', '', '', '', '', 0),
(863, 'plPL', 'Ucieczka', 'Pewnie nauczę się po drodze... Nie może to być takie trudne. Parę guzików tutaj, dźwignia czy dwie... No, jesteś $ggotów:gotowa; do drogi?', 'Chroń Wizzlecranka i skradziony gobliński rozdrabniacz w drodze do Sputtervalve\'a w Zapadce.', 'Wyprowadź Wizzlecranka z terenu odwiertu spółki Gitgeszeft', 'Wróć do Sputtervalve\'a w Zapadce na Pustkowiach.', '', '', '', '', 0),
(1097, 'plPL', 'Zadanie Elmore\'a', 'W Wichrogrodzie jest krasnoludzki płatnerz, Grimand Elmore, który dał znać, że potrzebuje pomocy przy dostawie. Zdaje się, że chce wysłać paczkę do swojej ojczyzny na północy.$B$BMasz mocne nogi! Więc jeśli nie boisz się trochę pobiegać, porozmawiaj z Grimandem. $GPrzydałbyś:Przydałabyś; się nam tutaj, ale musimy też dbać o dobre stosunki z krasnoludami.$B$BGrimanda Elmore\'a znajdziesz w sklepie z bronią w Dzielnicy Krasnoludów w Wichrogrodzie, w północno-wschodniej części miasta.', 'Porozmawiaj z Grimandem Elmore\'em w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1638, 'plPL', 'Szkolenie wojownika', '$GPokazałeś:Pokazałaś;, że $gjesteś kompetentnym wojownikiem:jesteś kompetentną wojowniczką;, $N. Ale wciąż $gjesteś młody:jesteś młoda; i wiele musisz się nauczyć.$B$BPorozmawiaj z Harrym Burlguardem – zwykle przesiaduje w tawernie „Świnia i Gwizdek” na Starym Mieście w Wichrogrodzie. Harry to stary weteran i dobry nauczyciel. Pokaże ci kilka ruchów, dzięki którym dłużej pooddychasz.', 'Porozmawiaj z Harrym Burlguardem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1641, 'plPL', 'Księga Boskości', '', '', '', '', '', '', '', '', 0),
(1642, 'plPL', 'Księga Boskości', 'We wszystkim paladyn musi odzwierciedlać Światłość, która wspiera naszą siłę. Dążenie do boskości nie oznacza dla nas pragnienia, by stać się bogiem – dążymy do tego, by każdy nasz czyn był dobry.$B$BChoć w tych ciężkich czasach jesteśmy wzywani do gromienia zła, zawsze musisz pamiętać, że to pomoc innym naprawdę wyróżni cię spośród mieszkańców Azeroth. Współczucie, cierpliwość, odwaga – to wszystko znaczy dla paladyna tyle samo, co siła w bitwie.$B$BZapamiętaj to dobrze i nigdy nie zapominaj.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1643, 'plPL', 'Księga Boskości', 'Twoim zadaniem, $N, jest więc znalezienie w Wichrogrodzie kogoś, kto potrzebuje pomocy. Kogoś o czystym sercu i czystych pobudkach. Może kogoś, kto sam pomaga innym. Może kogoś, kto potrzebuje przewodnika. Tak czy inaczej, ta osoba musi mieć szlachetne zamiary i liczyć na twoją życzliwość.$B$BZrób to i wróć do mnie, gdy skończysz. Wtedy porozmawiamy więcej o twojej ścieżce i o tym, co znaczy być paladynem Światłości.', 'Poszukaj Stephanie Turner w Dzielnicy Handlowej Wichrogrodu.', '', '', '', '', '', '', 0),
(1644, 'plPL', 'Księga Boskości', 'Biedactwa, większość z nich straciła rodziny w atakach Plagi w ostatnim dziesięcioleciu.$B$BMój mąż John zbiera dla mnie materiały, z których szyję dzieciom koszule i spodnie, ale nawet na to nie mam czasu. Skupiam się na tym, żeby miały co jeść i dach nad głową.$B$BCo takiego? Chcesz pomóc? Och, dzięki niech będą Światłości, i dziękuję ci, $N.$B$BGdybyś $gmógł:mogła; przynieść mi trochę lnianego płótna, żebym uszyła dzieciom ubrania, bardzo by mi to pomogło.', 'Przynieś 10 sztuk lnianego płótna Stephanie Turner w Wichrogrodzie.', '', 'Wróć do Stephanie Turner w Wichrogrodzie.', '', '', '', '', 0),
(1645, 'plPL', 'Księga Boskości', '', '', '', '', '', '', '', '', 0),
(1646, 'plPL', 'Księga Boskości', 'We wszystkim paladyn musi odzwierciedlać Światłość, która wspiera naszą siłę. Dążenie do boskości nie oznacza dla nas pragnienia, by stać się bogiem – dążymy do tego, by każdy nasz czyn był dobry.$B$BChoć w tych ciężkich czasach jesteśmy wzywani do gromienia zła, zawsze musisz pamiętać, że to pomoc innym naprawdę wyróżni cię spośród mieszkańców Azeroth. Współczucie, cierpliwość, odwaga – to wszystko znaczy dla paladyna tyle samo, co siła w bitwie.$B$BZapamiętaj to dobrze i nigdy nie zapominaj.', 'Porozmawiaj z Tizą Bojokuć w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1647, 'plPL', 'Księga Boskości', 'Twoim zadaniem, $N, jest więc znalezienie w Żelaznej Kuźni kogoś, kto potrzebuje pomocy. Kogoś o czystym sercu i czystych pobudkach. Może kogoś, kto sam pomaga innym. Może kogoś, kto potrzebuje przewodnika. Tak czy inaczej, ta osoba musi mieć szlachetne zamiary i liczyć na twoją życzliwość.$B$BZrób to i wróć do mnie, gdy skończysz. Wtedy porozmawiamy więcej o twojej ścieżce i o tym, co znaczy być paladynem Światłości. Będę czekać na twój powrót tutaj, w świątyni. Inni paladyni także będą potrzebować moich wskazówek.', 'Poszukaj Johna Turnera w zewnętrznym kręgu Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1648, 'plPL', 'Księga Boskości', 'Razem z żoną prowadzimy sierociniec w Wichrogrodzie, głównie dla dzieci, które straciły rodziców podczas ataków Plagi w ostatnim dziesięcioleciu. Mniej więcej co miesiąc przyjeżdżam do Żelaznej Kuźni, żeby zebrać od tutejszych mieszkańców trochę zapasów i porozmawiać z różnymi grupami, czy mogą jakoś pomóc.$B$BTa podróż ciągnie się niemiłosiernie i niewiele z niej wynikło.$B$BGdybym tylko zdobył jeszcze trochę lnu, z którego żona uszyłaby ubrania, mógłbym wreszcie wysłać do domu transport.', 'Przynieś 10 sztuk lnianego płótna Johnowi Turnerowi w Żelaznej Kuźni.', '', 'Wróć do Johna Turnera w Dun Morogh.', '', '', '', '', 0),
(1649, 'plPL', 'Księga Męstwa', 'Męstwo i wszystkie towarzyszące mu cnoty są jak rzadkie minerały: trzeba je cenić, gdy się je znajdzie, bo są wiele warte, ale trzeba też poświęcić czas, by je wydobyć... i oczyścić. Właściwie połączone tworzą mocny stop, którego czasem nie skruszą nawet najpotężniejsze ciosy.$B$BTa siła, twoja wiara, twoja odwaga muszą zostać wystawione na próbę. Musisz nauczyć się nigdy nie tracić wiary i zrozumieć, że dzięki mocy Światłości zdołasz pokonać to, czego większość innych nie potrafi.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1652, 'plPL', 'Księga Męstwa', 'Proszę, wróć do Duthoriana i powiedz mu, że na razie jestem bezpieczna. Zawdzięczam to tobie i Kościołowi.$B$BOn przekaże wiadomość do Żelaznej Kuźni, żeby mój Jordan wiedział, że nie ma się czego obawiać.$B$BOch, jak ja tęsknię za mężem. Nie mogę się doczekać, aż wróci.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1661, 'plPL', 'Księga Szlachetności', 'Witam cię ponownie, $N. Z większą dumą niż kiedykolwiek nazywam cię $gbratem:siostrą; – twoje oddanie przynosi zaszczyt nam wszystkim.$B$BNadszedł czas, bym obdarzył cię wielkim darem. Wiedz jednak, że teraz daję ci go bez żadnych warunków, lecz później, gdy czas pozwoli, będzie to znacznie większe wyzwanie dla wszystkich paladynów, którzy podejmą się mojego zadania.$B$BPorozmawiaj ze mną ponownie, a udzielę ci wielkiej łaski.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1666, 'plPL', 'Marszałek Haggard', '$GNauczyłeś:Nauczyłaś; się kilku ruchów, ale wciąż przydałaby ci się porządna broń. Założę się, że marszałek Haggard mógłby ci pomóc.$B$BMarszałek Haggard mieszka we dworze w Kniei Elwynn, przy obozie drwali we Wschodniej Dolinie. Jest już na emeryturze, ale przez lata służby zebrał mnóstwo sprzętu.$B$BPowiedz mu, że to ja cię przysyłam, a przy odrobinie szczęścia znajdzie dla ciebie jakąś zbędną broń.', 'Porozmawiaj z marszałkiem Haggardem.', '', '', '', '', '', '', 0),
(1667, 'plPL', 'Martwozęby Jack', 'Burlguard cię przysłał, tak? Owszem, mam tu trochę zbędnej broni, ale najpierw mam dla ciebie zadanie...$B$BJakiś czas temu oszukał mnie Martwozęby Jack, łotr z Bractwa Nieskornych. Było ciemno, miał na sobie tabard Wichrogrodu, a ja wziąłem go za marszałka Dughana. Powiedział, że potrzebuje mojej starej odznaki marszałka Wichrogrodu, a ja mu ją dałem... a on się roześmiał i uciekł, zanim zdążyłem go złapać!$B$BOdzyskaj moją odznakę! Martwozęby Jack pewnie schował ją w swoim obozie na południu.', 'Odzyskaj odznakę Haggarda z obozu Martwozębego Jacka i wróć do marszałka Haggarda.', '', 'Wróć do marszałka Haggarda nad Jeziorem Kamiennego Kopca w Kniei Elwynn.', '', '', '', '', 0),
(1685, 'plPL', 'Wezwanie od Gakina', 'Czy nie zawsze tak jest? Szukałem cię cały dzień i nie mogłem znaleźć, a teraz, kiedy się tego nie spodziewam, $gsam:sama; do mnie podchodzisz.$b$bStraciłem już dość czasu na szukanie cię, więc nie będę cię dłużej zatrzymywać. Mistrz Gakin wzywa cię na dalsze szkolenie. Moim zdaniem $gpowinieneś:powinnaś; odszukać go jak najszybciej.$b$bZnajdziesz go w piwnicy tawerny „Zarżnięte Jagnię”. A przy okazji, lepiej nie rozgłaszaj tego miejsca. Nie chcemy, żeby wieść się rozniosła.', 'Zamelduj się u Gakina Mrokospętacza w Dzielnicy Magów w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1715, 'plPL', '„Zarżnięte Jagnię”', 'Hmpf. Dawniej wszyscy czarnoksiężnicy w Khaz Modan szkolili się pod okiem mistrzów z Gnomoregan, ale teraz, kiedy musieliśmy się przenieść do tej szczurzej nory w Żelaznej Kuźni, a Magni postanowił pilnie nas obserwować, jesteśmy zmuszeni wysyłać nowicjuszy na szkolenie do Wichrogrodu.$b$bNa szczęście Gakin to nie byle kto, więc i tak nauczysz się tego, co trzeba, ale krew mnie zalewa!$b$bTak czy siak, Gakina znajdziesz w piwnicy tawerny „Zarżnięte Jagnię” w Wichrogrodzie.', 'Zamelduj się u Gakina Mrokospętacza w Dzielnicy Magów w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1717, 'plPL', 'Wezwanie od Gakina', '$n! Nie spodziewałem się ciebie w tych stronach, ale kazano mi wypatrywać twojego przybycia.$b$bNajwyższy czas, żebyś $gprzeszedł:przeszła; dalsze szkolenie, więc następnym razem, gdy będziesz w Wichrogrodzie, zajrzyj do Gakina. Będzie na ciebie czekał.', 'Zamelduj się u Gakina Mrokospętacza w Dzielnicy Magów w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1778, 'plPL', 'Księga Boskości', 'Zamierzam wkrótce zacząć szykować się do powrotu do domu. Mam nadzieję, że Stephanie dobrze sobie radzi w Wichrogrodzie. Nie mogę się doczekać, aż znów ją zobaczę. Do następnego spotkania, $N.', 'Porozmawiaj z Tizą Bojokuć w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1779, 'plPL', 'Księga Boskości', 'Chcę, żebyś to $gwziął:wzięła;, $N. To Symbol Życia.$B$B$GOkazałeś:Okazałaś; miłosierdzie i cierpliwość, a teraz chcę, żebyś $gudowodnił:udowodniła;, jak wielką biegłość $gosiągnąłeś:osiągnęłaś; zarówno w walce, jak i we władaniu mocą.$B$BMój mąż Muiredon niedawno wrócił ze starcia z krasnoludami z klanu Czarnorytych i ledwo uszedł z życiem – leży tam, a jeden z naszych kapłanów opatruje mu rany.$B$BWeź Symbol i porozmawiaj z nim. Jeśli zdołasz mu pomóc, wkrótce znów porozmawiamy. Niech Światłość świeci nad tobą.', 'Weź Symbol Życia i porozmawiaj z Muiredonem Bojokuciem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1780, 'plPL', 'Księga Boskości', 'Jeszcze dziś zaniosę to dzieciom. Proszę, uważaj na siebie, $N. Nieczęsto $gmężczyźni:kobiety; twojego pokroju pokazują się w mieście, ale $gudowodniłeś:udowodniłaś;, że paladyni z Wichrogrodu nigdy nie odwrócą się od potrzebujących.$B$BBywaj.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1781, 'plPL', 'Księga Boskości', 'Weź to, $N. To Symbol Życia.$B$B$GOkazałeś:Okazałaś; się $gmiłosierny:miłosierna; i $gcierpliwy:cierpliwa;, a teraz nadszedł czas, by sprawdzić, czy masz dość mocy, by skupić jeden z największych darów Światłości.$B$BMój przyjaciel Gazin wrócił niedawno ze starcia z Nieskornymi w Elwynn, w pobliżu Czuwania Bohaterów – ledwo uszedł z życiem. Jest przy ołtarzu, gdzie nasi kapłani leczą jego rany.$B$BWeź Symbol i porozmawiaj z nim. Jeśli zdołasz mu pomóc, wkrótce znów porozmawiamy. Niech opromienia cię chwała Światłości.', 'Zanieś Symbol Życia Gazinowi Tenormowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1785, 'plPL', 'Księga Boskości', 'Widzę stąd, jak moja żona już promienieje z dumy. Lepiej rusz tam migiem swoje cztery litery. Myślę, że będzie chciała zamienić z tobą parę słów.$B$BŚwiatłość z tobą, $N. Będę cię wypatrywał na polu bitwy przeciw Pladze i tym Czarnorytym, kiedy przyjdzie czas.', 'Porozmawiaj z Tizą Bojokuć w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1786, 'plPL', 'Księga Boskości', 'Razem z Henzem dotarliśmy do Czuwania Bohaterów, wyspy pośrodku Jeziora Kamiennego Kopca w północno-wschodnim Elwynn. Słyszeliśmy, że Nieskorni przeniknęli przez nasze granice, i chcieliśmy zdobyć dowód dla doradców króla.$B$BWypatrzyliśmy kilku tych szubrawców przeglądających jakieś dokumenty i zaatakowaliśmy. Niestety, szybko przytłoczyło nas więcej magów.$B$BHenze powstrzymywał ich, a ja uciekłem... głupiec, musiał zgrywać bohatera.$B$BWciąż tam jest, Henze. Pomożesz nam, $N?', 'Weź Symbol Życia i wskrześ Henzego Faulka w Elwynn.', '', '', '', '', '', '', 0),
(1787, 'plPL', 'Księga Boskości', 'O Symbolu porozmawiamy później. Teraz najważniejsze jest zdobycie tych papierów, które przeglądali Nieskorni. Jeśli wpadną w nasze ręce, udowodnimy, że Nieskorni przeniknęli do Elwynn, i być może dowiemy się, jakie mają plany.$B$BNa razie nie nadaję się do walki, $N. Myślisz, że jesteś $gdość silny:dość silna;, by odebrać te papiery Nieskornym tu, na wyspie?$B$BJeśli ci się uda, zanieś je Gazinowi i powiedz mu, że nic mi nie jest.', 'Zdobądź pismo Nieskornych od czarodziejów-łotrów Nieskornych w Elwynn i wróć do Gazina Tenorma w Wichrogrodzie.', '', 'Wróć do Gazina Tenorma w Wichrogrodzie.', '', '', '', '', 0),
(1788, 'plPL', 'Księga Boskości', 'Zaniosę te pisma doradcom króla, kiedy Duthorian je przejrzy, ale tymczasem idź porozmawiać z Duthorianem. Na pewno zechce cię poklepać po plecach!$B$BJeszcze raz dziękuję, $N. Mam nadzieję, że jeszcze się spotkamy. Jesteś $gsojusznikiem:sojuszniczką;, $gktórego:którą; z dumą nazywam przyjacielem.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1860, 'plPL', 'Porozmawiaj z Jenneą', 'My, magowie, mamy zadanie do wykonania. Zadanie kluczowe dla bezpieczeństwa Wichrogrodu i Kniei Elwynn.$B$BSzczegóły zna Jennea Cannon. Studiuje w sanktuarium czarodziejów, w Dzielnicy Magów w Wichrogrodzie. Udaj się do niej bez zwłoki.', 'Porozmawiaj z Jenneą Cannon w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1919, 'plPL', 'Zgłoś się do Jennei', 'Twoja wiedza o sztuce rośnie, $N. Czy jesteś już $ggotów:gotowa; rozpocząć prawdziwą naukę? Czy jesteś $ggotów:gotowa; zająć swoje miejsce w tajnej wojnie, którą toczymy?$B$BJeśli tak, porozmawiaj z Jenneą Cannon w sanktuarium czarodziejów w Dzielnicy Magów w Wichrogrodzie. Ma dla ciebie zadanie, które otworzy ci pierwsze okno na niewidzialny świat.', 'Porozmawiaj z Jenneą Cannon w Wichrogrodzie.', '', '', '', '', '', '', 0),
(2158, 'plPL', 'Odpoczynek i relaks', 'Każdy poszukiwacz przygód powinien odpocząć, gdy dopada go zmęczenie – a nie ma lepszego miejsca na odpoczynek i relaks niż karczma „Lwia Duma”!$B$BMój najlepszy przyjaciel, karczmarz Farley, prowadzi „Lwią Dumę”. Jeśli powiesz mu, że to ja cię przysyłam, może da ci specjalną zniżkę na jedzenie i picie.$B$BŻeby trafić do „Lwiej Dumy”, idź stąd drogą na południe – nie da się jej przeoczyć!', 'Porozmawiaj z karczmarzem Farleyem w karczmie „Lwia Duma”.', '', '', '', '', '', '', 0),
(2205, 'plPL', 'Odszukaj WW:7', 'Odznaka? Ach, to nic, płotko – nic, z czym $gdałbyś:dałabyś; sobie radę. Sądząc po twoim wyglądzie, Mathias pewnie weźmie cię raczej za $gchłopaka:dziewczynę; od dostawy sera niż za prawdziwego łotra. Tak czy inaczej, dostałam zlecenie i obiecałam je wykonać.$B$BA skoro o tym mowa, zanieś tę paczkę Mathiasowi, a może da ci jakieś drobne zadanie czy dwa.$B$BDo roboty.$B', 'Dostarcz paczkę Keryn Sylvius mistrzowi Mathiasowi Shaw w koszarach Wichrogrodu.', '', '', '', '', '', '', 0),
(2298, 'plPL', 'Królewska obława', 'No więc siedzim tu, mamy właśnie rozpisywać fazę III, a tu wpada paru tych tępaków Magniego i gada coś o jakimś skoku, i aresztuje paru z Ukrytego Kręgu.$B$BA starego Czarnobrodego nikt w kajdany nie zakuje! Dyskutacja zrobiła się gęsta i ciężka, i jakosik wypsnęło się twoje imię!$B$BMoja rada? Łap pierwszego gryfa z Żelaznej Kuźni i leć do Wichrogrodu. Idź na Stare Miasto i tam pogadaj z moim starym kumplem, Renzikiem „Kosa”.', 'Udaj się do Wichrogrodu i odszukaj Renzika „Kosę”.', '', '', '', '', '', '', 0),
(2300, 'plPL', 'WW:7', 'Renzik cię szukał, płotko.$B$BNa twoim miejscu nie kazałabym czekać zastępcy Mathiasa.$B', 'Udaj się do Wichrogrodu i odszukaj Renzika „Kosę”.', '', '', '', '', '', '', 0),
(2998, 'plPL', 'Księga Boskości', 'Witaj, $gbracie:siostro;. Duthorian Rall, jeden z naszych najbardziej wpływowych paladynów, niedawno o tobie mówił. Słyszałem, jak mówił, że nadszedł czas, by poddać cię próbie... i wypowiadał się bardzo pochlebnie o tym, jak dotąd się $gspisałeś:spisałaś;.$B$BNa twoim miejscu, gdy znajdziesz czas, udałbym się do Wichrogrodu i z nim porozmawiał. Na pewno jest w Katedrze Światła – tam spędza większość czasu.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(2999, 'plPL', 'Księga Boskości', 'Witaj, $N. Wiem, że masz pełne ręce roboty z pomaganiem mieszkańcom Dun Morogh, ale kiedy znajdziesz czas, $gpowinieneś:powinnaś; pójść na górę i porozmawiać z jedną z najbardziej szanowanych osób w naszym zakonie: Tizą Bojokuć. To do niej przychodzą młodsi paladyni, kiedy nadchodzi pora, by dowiedzieć się więcej o Światłości i o tym, czego się od nich oczekuje.', 'Porozmawiaj z Tizą Bojokuć w Żelaznej Kuźni', '', '', '', '', '', '', 0),
(3000, 'plPL', 'Księga Boskości', 'Witaj, $N. Wiem, że masz pełne ręce roboty, pomagając mieszkańcom Azeroth, ale kiedy znajdziesz czas, wróć do Żelaznej Kuźni i porozmawiaj z jedną z najbardziej szanowanych paladynek twojej ojczyzny: Tizą Bojokuć. To do niej przychodzą młodsi krasnoludzcy paladyni, gdy nadchodzi czas, by dowiedzieć się więcej o Światłości i o tym, czego oczekuje się od nas wszystkich.$B$BZnajdziesz ją na piętrze Sali Tajemnic w Dzielnicy Mistycznej.', 'Porozmawiaj z Tizą Bojokuć w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3100, 'plPL', 'Zwykły list', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią Llane\'a, naszego miejscowego nauczyciela wojowników. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj zwykły list i porozmawiaj z Llane\'em Beshere\'em w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(3101, 'plPL', 'Poświęcony list', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią brata Sammuela, naszego miejscowego nauczyciela paladynów. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj poświęcony list i porozmawiaj z bratem Sammuelem w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(3102, 'plPL', 'Zaszyfrowany list', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią Jorika, jednego z naszych miejscowych nauczycieli. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj zaszyfrowany list i porozmawiaj z Jorikiem Kerridanem w stajni za Opactwem Północnych Włości.', '', '', '', '', '', '', 0),
(3103, 'plPL', 'Uświęcony list', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią kapłanki Anetty, naszej miejscowej nauczycielki kapłanów. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj uświęcony list i porozmawiaj z kapłanką Anettą w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(3104, 'plPL', 'List z glifami', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią Kheldena, naszego miejscowego nauczyciela magów. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj list z glifami i porozmawiaj z Kheldenem Bremenem w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(3105, 'plPL', 'Skażony list', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią Drusilli, jednej z naszych miejscowych nauczycielek. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj skażony list i porozmawiaj z Drusillą La Salle obok Opactwa Północnych Włości.', '', '', '', '', '', '', 0),
(3681, 'plPL', 'Księga Boskości', 'Wybacz, że przerywam ci podróż, $N, ale uznałem, że musisz o tym wiedzieć: niedawno przyszła z Wichrogrodu wiadomość, że paladyni mają się tam stawić na szkolenie.$B$BJeśli się nie mylę, zbliża się dla ciebie szczególna chwila i czas, żebyś $gzaczął:zaczęła; studiować Księgi.$B$BSzukaj Duthoriana Ralla w Wichrogrodzie. Zwykle szkoli paladynów w Katedrze Światła.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(3861, 'plPL', 'KO-KO!', '„Ko... ko... ko... KOKOODAK!$B$BKo... ko... ko.”$B$BKura spogląda na ciebie, a potem zaczyna drapać pazurami ziemię. Masz wrażenie, że wypisuje jakieś słowo, ale nie wiesz jakie. Czy to może być... S-A-L-D-E-A-N? Zanim zdążysz zapytać, kura odwraca się i wraca do swoich spraw.', 'Znajdź specjalną karmę dla kur i wróć do zaprzyjaźnionej kury. Gdy ją znajdziesz, zrób /cheer w jej stronę, zanim spróbujesz dać jej specjalną karmę dla kur.', '', 'Wróć do kury.', '', '', '', '', 0),
(3903, 'plPL', 'Milly Osworth', '$N, $gpokazałeś:pokazałaś;, że można na tobie polegać. I że nie boisz się ubrudzić rąk, co?$B$BMam przyjaciółkę, Milly Osworth, która ma kłopoty. Stoi ze swoim wozem po drugiej stronie opactwa, niedaleko stajni. Na pewno przydałaby się jej para takich rąk jak twoje.', 'Porozmawiaj z Milly Osworth.', '', '', '', '', '', '', 0),
(3904, 'plPL', 'Plony Milly', 'Banda rozbójników, Nieskorni, wtargnęła do Winnic Północnych Włości, kiedy zbierałam winogrona! Zgłosiłam to straży Północnych Włości i zapewnili mnie, że się tym zajmą, ale... boję się o swoje winogrona! Jeśli Nieskorni ich nie ukradną, to obawiam się, że nasi strażnicy je stratują, przeganiając tych zbirów.$B$BProszę, musisz mi pomóc! Większość winogron zebrałam do wiader, ale zostawiłam je w winnicach na południowym wschodzie.$B$BPrzynieś mi te wiadra! Ocal moje plony!', 'Przynieś 8 skrzynek plonów Milly do Milly Osworth w Opactwie Północnych Włości.', '', 'Wróć do Milly Osworth w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(3905, 'plPL', 'Wykaz winogron', 'Skoro moje plony są uratowane, zanieś ten wykaz winogron bratu Nealsowi. Zarządza zapasami jadła i napitków w Północnych Włościach i na pewno ucieszy się, że ma świeże winogrona.$B$BBrata Nealsa znajdziesz w opactwie, w dzwonnicy... tam lubi kosztować swoje wino.', 'Zanieś wykaz winogron bratu Nealsowi w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(4485, 'plPL', 'Księga Szlachetności', 'Witaj, $N. Widzę, że twoje oddanie wciąż jest silne, podobnie jak twoja wiara.$B$BMyślę, że nadszedł czas, byś $gporozmawiał:porozmawiała; z Duthorianem Rallem w Wichrogrodzie. Czeka cię jeszcze kilka lekcji, a czuję, że jesteś $ggotów:gotowa;.$B$BOdszukaj go w Katedrze Światła i, $N, traktuj te lekcje poważnie. $GOsiągnąłeś:Osiągnęłaś; swoją pozycję dzięki pokorze i ciężkiej pracy, nie rozczaruj nas, popadając w arogancję.$B$BBywaj.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(4486, 'plPL', 'Księga Szlachetności', 'No proszę, proszę, spójrzcie tylko na $gpotężnego paladyna w całym jego:potężną paladynkę w całym jej; majestacie.$B$BWybacz, $N, nie chciałem cię urazić... Po prostu czasem trochę zazdroszczę, kiedy widzę niektóre z twoich dokonań. Tiza mówi, że to moja słabość, i przysiągłem jej, że będę nad tym pracował. Tylko że czasem jest ciężko, wiesz?$B$BAle chciałem z tobą porozmawiać, bo Duthorian Rall z Wichrogrodu przekazał, żebyś $gspotkał:spotkała; się z nim w Katedrze Światła, kiedy będziesz $ggotów:gotowa;. Brzmiało to poważnie. Wygląda na to, że coś się dzieje.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(5261, 'plPL', 'Eagan Skórołup', 'Eagan Skórołup szuka kogoś, kto zapoluje dla niego na chore wilki. To dobra wiadomość, bo ostatnio w Dolinie Północnych Włości widujemy coraz więcej chorych wilków.$B$BJeśli cię to interesuje, porozmawiaj z Eaganem. Znajdziesz go przy bocznej ścianie opactwa, po lewej.', 'Porozmawiaj z Eaganem Skórołupem.', '', '', '', '', '', '', 0),
(5545, 'plPL', 'Wiązka kłopotów', 'Mam prawdziwy kłopot. Zbliża się termin dostawy drewna, a czasu mam coraz mniej. Wilki i niedźwiedzie na północ stąd przegoniły moich robotników od wiązek drewna, które już narąbali.$B$BRozmawiałam już z zastępcą Rainerem o przepędzeniu zwierząt, ale potrzebuję kogoś, kto zbierze dla mnie drewno. Jeśli przyniesiesz mi osiem wiązek drewna, może jeszcze zdążę na czas.', 'Przynieś 8 wiązek drewna Raelen do obozu drwali we Wschodniej Dolinie.', '', 'Wróć do nadzorczyni Raelen w obozie drwali we Wschodniej Dolinie w Kniei Elwynn.', '', '', '', '', 0),
(5623, 'plPL', 'W łaskach Światłości', 'Witaj ponownie, $gmłody kapłanie:młoda kapłanko;. Nadszedł czas, byś $gpoznał:poznała; naszą wiarę głębiej. Gdy skończysz wszystkie swoje sprawy tu, w Północnych Włościach, odszukaj kapłankę Josettę w Złotych Włościach. Ma cię jeszcze wiele nauczyć i słyszała, że coraz mocniej kroczysz ścieżkami Światłości. Nie może się doczekać dalszych nauk.', 'Porozmawiaj z kapłanką Josettą w Kniei Elwynn.', '', '', '', '', '', '', 0),
(5624, 'plPL', 'Szaty Światłości', 'Zwykle wyznaczam wyznawcom Światłości niewielką próbę, by sprawdzić ich umiejętności. Chcę zobaczyć, czy są godni nosić swoje pierwsze szaty – znak, że Kościół otwarcie uznaje $gkapłana:kapłankę; i $ggo:ją; wspiera.$B$BAle tym razem sytuacja jest nieco inna. Jeden z mieszkańców Złotych Włości widział rannego strażnika przy jeziorze na wschód stąd. Nazywa się Roberts. Znajdź go, ulecz, wzmocnij jego ciało i wróć tutaj. Jeśli to dla mnie zrobisz, uznam twoją próbę za zaliczoną.', 'Znajdź strażnika Robertsa i ulecz jego rany Pomniejszym leczeniem (ranga 2). Następnie obdarz go Słowem mocy: Wytrwałość i wróć do kapłanki Josetty w Złotych Włościach.', '', 'Wróć do kapłanki Josetty w Kniei Elwynn.', 'Ulecz i wzmocnij strażnika Robertsa', '', '', '', 0),
(5805, 'plPL', 'Witaj!', 'Witaj w World of Warcraft!$B$BW ramach szczególnego podziękowania za zakup Edycji Kolekcjonerskiej World of Warcraft oddaj ten bon podarunkowy Merissie Stilwell w Złotych Włościach. Otrzymasz w zamian prezent: małego towarzysza, który będzie ci towarzyszyć w poszukiwaniu przygód i chwały.$B$BJeszcze raz dziękujemy i życzymy miłego pobytu w World of Warcraft!$B', 'Zanieś bon podarunkowy ze Złotych Włości Merissie Stilwell w Złotych Włościach.', '', '', '', '', '', '', 0),
(5842, 'plPL', 'Witaj!', 'Witaj w World of Warcraft!$B$BW ramach szczególnego podziękowania za zakup Edycji kolekcjonerskiej World of Warcraft oddaj ten bon podarunkowy Orenthilowi Szeptowi Wiatru w Dolanaar. Otrzymasz wtedy prezent: małego kompana, który dołączy do ciebie w pogoni za przygodą i chwałą.$B$BJeszcze raz dziękujemy i życzymy udanego pobytu w World of Warcraft!', 'Przynieś bon podarunkowy z Dolanaar Orenthilowi Szeptowi Wiatru w Dolanaar.', '', '', '', '', '', '', 0),
(5844, 'plPL', 'Witaj!', 'Witaj w World of Warcraft!$B$BW podziękowaniu za zakup edycji kolekcjonerskiej World of Warcraft oddaj ten bon podarunkowy Vornowi Niebowidzowi w Wiosce Krwawego Kopyta. Otrzymasz wtedy prezent: małego towarzysza, który dołączy do ciebie w poszukiwaniu przygód i chwały.$B$BJeszcze raz dziękujemy i życzymy miłego pobytu w świecie World of Warcraft!', 'Zanieś bon podarunkowy z Wioski Krwawego Kopyta Vornowi Niebowidzowi w Wiosce Krwawego Kopyta.', '', '', '', '', '', '', 0),
(5847, 'plPL', 'Witaj!', 'Witaj w świecie World of Warcraft!$B$BW podziękowaniu za zakup Edycji kolekcjonerskiej World of Warcraft oddaj ten bon podarunkowy Claire Willower w Brill. Otrzymasz w zamian prezent: małego towarzysza, który będzie ci towarzyszył w poszukiwaniu przygód i chwały.$B$BJeszcze raz dziękujemy i życzymy miłego pobytu w świecie World of Warcraft!', 'Zanieś bon podarunkowy z Brill Claire Willower w Brill.', '', '', '', '', '', '', 0),
