(7907, 'plPL', 'Talia bestii Lunomroku', 'Teraz, gdy wszystkie karty bestii są zebrane w talię, w tajemniczy sposób pojawia się dziewiąta karta z takim samym rewersem jak pierwszych osiem. Widnieje na niej napis: „Zwróć te karty Festynowi Lunomroku, a czeka cię nagroda”. Podobno festyn ten co kilka miesięcy zatrzymuje się na przemian w Mulgorze i w Złotych Włościach, więc trzeba będzie poczekać, aż znów tu zawita.', 'Zwróć talię bestii Festynowi Lunomroku, gdy ten zawita w okolicę.', '', '', '', '', '', '', 0),
(7927, 'plPL', 'Talia portali Lunomroku', 'Teraz, gdy wszystkie karty portali są zebrane w talię, w tajemniczy sposób pojawia się dziewiąta karta z takim samym rewersem jak pierwszych osiem. Widnieje na niej napis: „Zwróć te karty Festynowi Lunomroku, a czeka cię nagroda”. Podobno festyn ten co kilka miesięcy zatrzymuje się na przemian w Mulgorze i w Złotych Włościach, więc trzeba będzie poczekać, aż znów tu zawita.', 'Zwróć talię portali Festynowi Lunomroku, gdy ten zawita w okolicę.', '', '', '', '', '', '', 0),
(7928, 'plPL', 'Talia wodzów Lunomroku', 'Teraz, gdy wszystkie karty wodzów są zebrane w talię, w tajemniczy sposób pojawia się dziewiąta karta z takim samym rewersem jak pierwszych osiem. Widnieje na niej napis: „Zwróć te karty Festynowi Lunomroku, a czeka cię nagroda”. Podobno festyn ten co kilka miesięcy zatrzymuje się na przemian w Mulgorze i w Złotych Włościach, więc trzeba będzie poczekać, aż znów tu zawita.', 'Zwróć talię wodzów Festynowi Lunomroku, gdy ten zawita w okolicę.', '', '', '', '', '', '', 0),
(7929, 'plPL', 'Talia żywiołaków Lunomroku', 'Teraz, gdy wszystkie karty żywiołaków są zebrane w talię, w tajemniczy sposób pojawia się dziewiąta karta z takim samym rewersem jak pierwszych osiem. Widnieje na niej napis: „Zwróć te karty Festynowi Lunomroku, a czeka cię nagroda”. Podobno festyn ten co kilka miesięcy zatrzymuje się na przemian w Mulgorze i w Złotych Włościach, więc trzeba będzie poczekać, aż znów tu zawita.', 'Zwróć talię żywiołaków Festynowi Lunomroku, gdy ten zawita w okolicę.', '', '', '', '', '', '', 0),
