(14177, 'plPL', 'Ach, znów ten pyszny chleb umarłych, dziękuję!$B$BProszę, weź to w zamian... mały drobiazg dla zabawy z okazji święta.', 0),
(25415, 'plPL', 'Dobra robota, $N. Na początku może być niezręcznie, ale przywykniesz do publicznego głoszenia naszej wiary. To jeden ze sposobów, by pamiętać o naszym obowiązku niesienia prawdy innym. Musimy dawać nadzieję wszystkim, bo wszyscy razem stajemy w obliczu końca tego świata.', 0),
(25416, 'plPL', 'Teraz, gdy rozumiesz plan Mistrza, musisz przygotować się do odegrania swojej roli w jego urzeczywistnieniu.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(5, 'plPL', 'Och, przesyłka od mojego brata? Wspaniale! Szczęście naprawdę mi dziś sprzyja!', 0),
(6, 'plPL', '$GZnalazłeś:Znalazłaś; szopę Garricka? Czy w końcu pozbyliśmy się tego łotra?', 0),
(7, 'plPL', 'Jak idą łowy, $N? $GZnalazłeś:Znalazłaś; i $gpokonałeś:pokonałaś; te szkodniki?', 0),
(11, 'plPL', 'Witaj, $N. $GZabijałeś:Zabijałaś; gnole...?', 0),
(15, 'plPL', '$GByłeś:Byłaś; w kopalni? Jesteś $ggotów:gotowa; złożyć raport?', 0),
(16, 'plPL', 'Praca na roli wzmaga pragnienie, a ja zawsze szukam orzeźwiającej wody źródlanej.$B$BJeśli jakąś masz, chętnie się wymienię.', 0),
(18, 'plPL', '$GZebrałeś:Zebrałaś; już dla mnie te chusty?', 0),
(21, 'plPL', 'Wiem, że to krwawa robota, $N, ale od niej zależy bezpieczeństwo Północnych Włości. Jesteś $ggotów:gotowa; złożyć raport?', 0),
(33, 'plPL', 'Hej, $N. Jak idzie polowanie na chore młode wilki?', 0),
(46, 'plPL', 'Jak idą łowy, $N?', 0),
(47, 'plPL', 'Psst! Masz dla mnie ten złoty pył... dla mnie?', 0),
(52, 'plPL', '$GZabiłeś:Zabiłaś; te wilki i niedźwiedzie?', 0),
(54, 'plPL', 'Masz wieści od McBride\'a? Północne Włości to ogródek w porównaniu z Knieją Elwynn, ale ciekawe, co marszałek McBride ma do zameldowania.$b$bDaj mi jego dokumenty...', 0),
(59, 'plPL', 'Armia Wichrogrodu zleciła mi zaopatrywanie swoich ludzi w zbroje z płótna i skóry.$b$bJeśli masz dla mnie znacznik, chętnie coś dla ciebie zrobię.', 0),
(60, 'plPL', '$GZebrałeś:Zebrałaś; już te świece?', 0),
(61, 'plPL', 'Och, przesyłka od mojego brata? Wspaniale! Szczęście naprawdę mi dziś sprzyja!', 0),
(62, 'plPL', 'Co masz do zameldowania, $N? $GByłeś:Byłaś; w Kopalni Dalekiej Głębi?', 0),
(70, 'plPL', 'Co tam masz? Daj mi na to zerknąć...', 0),
(71, 'plPL', 'Witaj, $N. $GOdkryłeś:Odkryłaś;, co się stało z Rolfem i Malakaiem?', 0),
(74, 'plPL', 'Co tam masz? Nie widzę. Mam bardzo słaby wzrok. Daj mi to do rąk.', 0),
(75, 'plPL', '$GZnalazłeś:Znalazłaś; tę stronę, o której mówiłem, $N?', 0),
(76, 'plPL', 'Witaj, $N. Co masz do zameldowania? $GZbadałeś:Zbadałaś; Kopalnię Jaspisowej Żyły?', 0),
(78, 'plPL', 'To marszałek Haggard cię przysłał? Czemu od razu nie mówisz?$B$BAch, stary dobry Haggard. Biedak niedługo całkiem oślepnie. W każdym razie pokaż, co tam masz.', 0),
(83, 'plPL', 'Kończy mi się len, $N. Masz coś dla mnie?', 0),
(84, 'plPL', 'Uch... umieram z głodu! Masz dla mnie ten placek, $N?', 0),
(86, 'plPL', 'Nie uważam, że to w porządku karmić chłopaka, który w ogóle ukradł mi naszyjnik, ale jeśli tylko tak odzyskam to, co moje, niech tak będzie!$b$bMasz tę dziczyznę?', 0),
(87, 'plPL', 'Witaj, $N. $GZnalazłeś:Znalazłaś; mój naszyjnik?', 0),
(88, 'plPL', '$GWidziałeś:Widziałaś; ją już? $GDopadłeś:Dopadłaś; ją?', 0),
(94, 'plPL', 'Ten posąg lwa stoi tu od dziesięcioleci i samotnie strzeże osławionej Wieży Ilgalara.$B$BU podstawy posągu jest wgłębienie, w którym można by osadzić klejnot albo glif...', 0),
(106, 'plPL', 'Co masz?? Maybell to światło mojego szarego życia. Szybko, pokaż mi jej list!', 0),
(107, 'plPL', 'Masz liścik od „Babci” Stonefield, tak? Nie widziałem Mildred od lat! Ciekawe, co ma do powiedzenia...', 0),
(109, 'plPL', 'I... i jak??', 0),
(111, 'plPL', 'Nie mogę się doczekać, jak zareagują moi przyjaciele!$B$BNigdy się tego nie spodziewają', 0),
(112, 'plPL', 'Masz te kryształowe wodorosty? Maybell na pewno nie może się doczekać spotkania ze swoim ukochanym...', 0),
(114, 'plPL', '$GDostarczyłeś:Dostarczyłaś; mój list Tommy\'emu Joe? Co powiedział??', 0),
(118, 'plPL', 'Co takiego? Verner cię przysłał, mówisz? No to dawaj jego liścik. I MÓW GŁOŚNIEJ!', 0),
(119, 'plPL', 'Świetnie, $gwróciłeś:wróciłaś;! Masz podkowy?', 0),
(123, 'plPL', 'Co?!? Od miesięcy nie mamy żadnych naszych ludzi w kopalniach Elwynn!$B$BPokaż mi ten liścik...', 0),
(147, 'plPL', '$GZnalazłeś:Znalazłaś; Kolekcjonera? $GOdkryłeś:Odkryłaś;, dla kogo pracuje?', 0),
(176, 'plPL', 'Tak, Wyżer dał się mocno we znaki mnie i moim ludziom. Masz coś do zameldowania w sprawie tej bestii?', 0),
(178, 'plPL', 'Mówisz, że przemówiłem do ciebie przez wisior? Hmm... daj mi go, żebym mógł go zbadać.', 0),
(249, 'plPL', 'Pospiesz się, $N, zanim moje obawy przed tym, że Morganth rozszerzy swoją władzę, się ziszczą!', 0),
(346, 'plPL', 'Udało ci się znaleźć księgę?', 0),
(347, 'plPL', 'Masz rudę z Rethbanu?', 0),
(1667, 'plPL', 'Masz moją odznakę? Nie chcę nawet myśleć, jakich szkód mógłby nią narobić Martwozęby Jack.', 0),
(1787, 'plPL', 'Czy Henze jest bezpieczny, $N? Udało ci się?$B$BZ twoją biegłością w walce i mocą Światłości Czuwanie Bohaterów jest chyba bezpieczne przed zagrożeniem ze strony Nieskornych, ale to już ocenią król i jego doradcy.', 0),
(2205, 'plPL', 'W czym mogę pomóc?', 0),
(3100, 'plPL', 'Ach, $gdostałeś:dostałaś; mój list, $N... dobrze.$B$BOstatnio do Elwynn napłynęło sporo wojowników – co dobrze wróży Wichrogrodowi, ale źle koboldom i Nieskornym w okolicy.', 0),
(3101, 'plPL', 'W końcu! Spotykamy się twarzą w twarz, $gbrat z bratem:brat z siostrą;. Witam cię w Północnych Włościach. Przez krótki czas będzie to twój dom, póki nie poznasz wszystkich tajników, ale wiedz, że Wichrogród jest niedaleko i prędzej czy później twoja ścieżka cię tam zaprowadzi. Do tego czasu bądź $gcierpliwy:cierpliwa;... $gRycerzu:Rycerko; Srebrnej Dłoni.', 0),
(3102, 'plPL', '$GDotarłeś:Dotarłaś; tu w jednym kawałku i nie wygląda na to, żeby wiele osób cię widziało. Jak dla mnie wystarczy. Nie lubię zwracać na siebie uwagi... tu, z tyłu, jest miło i cicho. Na pewno rozumiesz.$b$bJakieś kłopoty? Cieszę się, że nie. Wkrótce się to zmieni.', 0),
(3103, 'plPL', 'Ach, nareszcie jesteś. Wiedziałam, że trafisz do mnie. Święta Światłość jaśnieje nad tobą i nad ścieżką, którą $gobrałeś:obrałaś;. Nastały ciężkie czasy – Płonący Legion wciąż jest obecny w Azeroth, cały Kalimdor szuka nowych sposobów obrony przed własnymi utrapieniami, a do ciebie należy nieść pomoc tak wielu, jak tylko zdołasz.', 0),
(3104, 'plPL', 'Witaj, $N. Jestem Khelden. Mogę coś dla ciebie zrobić?', 0),
(3105, 'plPL', 'Ach, więc $gprzybyłeś:przybyłaś;, i to w samą porę, $N. Przed chwilą kręcili się tu strażnicy i dziwnie mi się przyglądali... żałośni prostaczkowie.', 0),
(3861, 'plPL', 'Kura wpatruje się w ciebie ciemnymi, zimnymi oczami. Czeka na ciebie głodna.$B$B„KOKOOODAK!$B$BKo... ko... ko.”', 0),
(3904, 'plPL', 'Masz moje plony, $N?', 0),
(3905, 'plPL', 'Widzę, że dopisuje ci humor! Chodź! Usiądź i napij się!', 0),
(5545, 'plPL', 'Termin się nie oddala. Proszę, pospiesz się i zbierz te wiązki drewna.', 0),
(5624, 'plPL', 'Jak być może już wiesz, nasza magia uzdrawiania jest niezbędna do przetrwania naszego ludu w tych ciężkich czasach – zwłaszcza dla poszukiwaczy przygód i bohaterów, którzy chwytają za broń i magię, by odpierać tak wiele różnych zagrożeń.$B$BDobrze zrobisz, jeśli zawsze będziesz pamiętać, jak ważna jest ta umiejętność. W połączeniu z Wytrwałością sprawia, że twoi towarzysze są w walce znacznie skuteczniejsi, bo wytrzymują o wiele więcej ciosów.$B$BNie pozwól nikomu lekceważyć potęgi twojej magii.', 0),
(5805, 'plPL', 'Witaj! Miło cię poznać!$B$BWidzę, że masz specjalny bon. Daj mi go, a dam ci coś w zamian.', 0),
(5842, 'plPL', 'Witaj! Miło cię poznać!$B$BWidzę, że masz specjalny bon. Daj mi go, a dam ci coś w zamian.', 0),
(5844, 'plPL', 'Witaj! Miło cię poznać!$B$BWidzę, że masz specjalny bon. Daj mi go, a dam ci coś w zamian.', 0),
(5847, 'plPL', 'Witaj! Miło cię poznać!$B$BWidzę, że masz specjalny bon. Daj mi go, a dam ci coś w zamian.', 0),
(6185, 'plPL', 'I... i jak??', 0),
(7881, 'plPL', 'My z Festynu Lunomroku dużo chodzimy. Wędrujemy z jednego miejsca festynu na drugie... prawdę mówiąc, nigdy nie zobaczysz, żebyśmy siedzieli w pracy! Nic więc dziwnego, że zdzieramy mnóstwo butów! Potrzebujemy butów trwałych i zarazem eleganckich, a buty z tłoczonej skóry nadają się do tego doskonale.$B$BTy! Znasz się na garbarstwie. Zrób mi buty z tłoczonej skóry, a za tę pracę dam ci kupon Festynu Lunomroku.', 0),
(7882, 'plPL', 'Pracownicy naszego Festynu robią więcej, niż tylko zamiatają śmieci i wbijają paliki! Pomagają też strzec festynu w podróży, dlatego stale potrzebują porządnych, mocnych kaftanów ochronnych.$B$BJeśli zrobisz kilka utwardzonych skórzanych zbroi i mi je przyniesiesz, dopilnuję, żeby trafiły do właściwych osób. W zamian dostaniesz ode mnie kupony Festynu Lunomroku.', 0),
(7883, 'plPL', 'Yebb Neblegear chce wzbogacić swój pokaz o nowe talenty i szuka po całym świecie największego gnoma, jaki istnieje. Znasz może jakieś gnomy słusznych rozmiarów?$B$BZanim go znajdzie, chce mieć gotowy kostium. Myślę, że dobrą podstawą kostiumu byłaby barbarzyńska uprząż. Możesz zrobić kilka takich uprzęży i mi je przynieść? Jeśli tak, będę miał dla ciebie plik kuponów Festynu Lunomroku...', 0),
(7884, 'plPL', 'Yebb pracuje nad kolejnymi atrakcjami swojego zoo, w tym nad wilgotnymi, bagnistymi siedliskami dla chłopca wychowanego przez krokoliszki i być może dla murloka. Będą nam potrzebne porządne, wodoszczelne nogawice, żebyśmy nie przemokli przy rozstawianiu i zwijaniu wystawy. Myślę, że nogawice z żółwich łusek będą w sam raz.$B$B$N, możesz zrobić takie nogawice? Jeśli tak, w nagrodę dostaniesz gruby plik kuponów Festynu Lunomroku...', 0),
(7885, 'plPL', 'Może nie zdajesz sobie z tego sprawy, ale prowadzenie wędrownego festynu sporo kosztuje! Wszystko zużywa się tak szybko, że aż dziw, że w ogóle wychodzimy na swoje.$B$BPrzez te wszystkie ukryte koszty ciągle szukamy sposobów, by jak najtaniej utrzymać sprzęt. Nasze namioty, na przykład, co rusz się drą, ale odkryłem, że skórzane zestawy pancerne to świetne łaty. Możesz zdobyć i przynieść mi kilka zestawów pancernych? Zaoszczędzimy na tym fortunę! Jeśli to zrobisz, mam dla ciebie garść kuponów Festynu Lunomroku...', 0),
(7889, 'plPL', 'Żeby być najsilniejszą kobietą na świecie, trzeba się nieźle napracować! Mój zestaw ciężarów robi się za lekki, a jeśli mam utrzymać formę, potrzebuję nowych obciążników!$B$BMyślisz, że $gmógłbyś:mogłabyś; przynieść mi kilka obciążników? Jeśli tak, dam ci kupon Festynu Lunomroku.', 0),
(7890, 'plPL', 'Na treningu lubię zakładać ciężkie kamienie szlifierskie na oba końce kija, a potem podnosić go nad głowę. To nie jest łatwe, ale tytułu najsilniejszej kobiety na świecie, a ja nią jestem, nie zdobywa się na siedząco!$B$BPomożesz mi? Potrzebuję więcej kamieni szlifierskich – przynieś mi kilka, a wymienię je na kupony Festynu Lunomroku.', 0),
(7891, 'plPL', 'Pracuję nad nowym kostiumem na czas, gdy będę miała własne stoisko jako najsilniejsza kobieta na świecie! Szukam teraz karwaszy, które mogłabym nosić. Nie mogą za dużo zasłaniać, bo ludzie chcą widzieć moje mięśnie, ale chciałabym też błysnąć odrobiną koloru, rozumiesz?$B$BCo powiesz na karwasze z zielonego żelaza, $N? Możesz mi takie wykuć? Jeśli tak, mam dla ciebie całe mnóstwo kuponów Festynu Lunomroku.', 0),
(7892, 'plPL', 'W moim numerze najsilniejszej kobiety na świecie zamierzam brać od widzów różne przedmioty i rozbijać je dużym czarnym buzdyganem!$B$BMożesz mi wykuć duży czarny buzdygan, $N?', 0),
(7893, 'plPL', '$N, dążąc do tego, by zostać najsilniejszą kobietą na świecie, przemierzyłam cały świat i poznałam sekrety budowania mięśni od dalekich mistrzów ciężarów, guru siły i ze starożytnych podręczników. Znam teraz zakazane ćwiczenia, które słabych by zabiły, a niewtajemniczonych okaleczyły!$B$BTakie wyczyny siły i wytrzymałości wymagają treningu z najgęstszymi kamieniami szlifierskimi. $N, możesz zdobyć albo zrobić gęste kamienie szlifierskie i mi je przynieść? Dam ci za to kupony...', 0),
(7894, 'plPL', 'Yebb przygotowuje nową atrakcję dla Zoo Osobliwości, taką, od której ludzie oszaleją z podziwu i zachwytu! Ale to wymaga mnóstwa pracy i mnóstwa materiałów...$B$BW tym miedzianych modulatorów. Potrzebujemy ich całej masy do mechanicznych części atrakcji. Przynieś mi miedziane modulatory, a w zamian dam ci kupon Festynu Lunomroku.', 0),
(7895, 'plPL', 'Moje nowe stoisko to będzie coś, co trzeba zobaczyć, o tak! Zobaczyć, a... nieliczni szczęśliwcy będą mogli też dotknąć!$B$BJuż słyszę, jak warczące brązowe gadżety śpiewają swą pieśń mechanicznego uniesienia, gdy goście podchodzą do mojego stoiska i sprawdzają swoje umiejętności!$B$BAch... teraz potrzebuję samych gadżetów, by przybliżyć to marzenie do spełnienia. Proszę, $N, przynieś mi warczące brązowe gadżety... a kupony Festynu Lunomroku będą twoje!', 0),
(7896, 'plPL', 'Kiedy wreszcie uruchomię to stoisko, będę chciał je zareklamować! A czy jest lepsza reklama niż fajerwerki?$B$BCóż, niektórzy mogliby uznać, że tłumy lepiej przyciąga zapach kotła, w którym gotują się głowy twoich wrogów, ale... jesteśmy w mieszanym towarzystwie. Muszą więc wystarczyć fajerwerki!$B$BPrzynieś mi zielone fajerwerki, $N, a mam dla ciebie pełną garść kuponów Festynu Lunomroku.', 0),
(7897, 'plPL', 'Najważniejszy powód, dla którego nie mogę otworzyć stoiska, jest taki, że... wszystko jest zepsute! Potrzebuję mechanicznych zestawów naprawczych, żeby to wszystko naprawić!$B$BMożesz mi przynieść takie zestawy, $N? Wymienię się... zestawy za kupony Festynu Lunomroku. Co ty na to?', 0),
(7898, 'plPL', 'Yebb Neblegear, tak jak ja, pracuje nad przyszłą atrakcją. Yebb mówi, że będzie tak niesamowita, że ściągnie ludzi z całego świata... i uczyni nas wszystkich bardzo, bardzo bogatymi!$B$BMówi, że do budowy potrzebuje ustrojstw z torium, i chce, żebym je dla niego zbierał. Co ty na to, $N? Wiesz, skąd wziąć ustrojstwa z torium? Jeśli znasz się na inżynierii, potrafisz je skonstruować? Chcesz je wymienić na kupony Festynu Lunomroku?', 0),
(7899, 'plPL', 'Pierwsza lekcja przyciągania tłumów brzmi: zwab ich gadżetami i świecidełkami! Pomożesz mi?$B$BPotrzebuję małych futrzanych łapek na nagrody. Znajdziesz je u kotów na Pustkowiach albo na Mrocznym Wybrzeżu...$B$BPrzynieś mi trochę łapek, a wymienię je na kupon Festynu Lunomroku.', 0),
(7900, 'plPL', 'Dzieci uwielbiają zabawki! I przekonałem się, że bez względu na rasę wszystkie dzieci uwielbiają futrzane, pluszowe zabawki z podartych niedźwiedzich skór!$B$BTakie skóry zdobędziesz na niedźwiedziach w Jesionowej Kniei albo w Międzygórzu. Przynieś mi ich całą stertę, a zarobisz stertę kuponów Festynu Lunomroku!', 0),
(7901, 'plPL', 'Zadziwiające, co ludzie potrafią cenić! Weźmy na przykład drewniany kijek z przyczepionym miękkim puszystym ogonem. Ty i ja moglibyśmy uznać, że coś takiego nie jest wiele warte... ale jeśli nadasz temu rupieciowi chwytliwą nazwę, na przykład „Dziki puszysty ogon”, i włożysz go do ładnego pudełka, ludzie uznają, że to coś cennego. Śmieć staje się skarbem!$B$BPrzynieś mi miękkie puszyste ogony wilków z Mrocznego Pustkowia i Bezludzia, a dam ci kupony Festynu Lunomroku.', 0),
(7902, 'plPL', 'Wyobraźnia to niezwykła rzecz. Sprawia, że najmniejszy pagórek wydaje się największą górą. Że najbardziej niewinny cień wygląda, jakby rzucał go straszliwy koszmar!$B$BMy na Festynie Lunomroku pozwalamy rozkwitać wyobraźni naszych gości! Ale żeby ją trochę rozruszać... czasem musimy uciec się do sztuczek.$B$BDo jednej z moich atrakcji potrzebuję barwnych piór. Zdobędziesz je na ptakach z niebezpieczniejszych rejonów Azeroth. Przynieś mi pióra, a dostaniesz wiele kuponów!', 0),
(7903, 'plPL', 'Zdarza ci się wędrować późną nocą po jaskini w poszukiwaniu przygód? Tak? Naprawdę? No to $gwidziałeś:widziałaś; upiorne ślepia nietoperzy, które gapią się na ciebie z góry i czekają, aż stracisz czujność, żeby wyssać ci krew!$B$BStraszna myśl, nie sądzisz? Oczywiście! Nie ma wątpliwości, że oczy nietoperzy są straszne!$B$BPrzyniesiesz mi kilka złych oczu nietoperzy, $N? Potrzebuję ich do... czegoś, co projektuję. Czegoś strasznego.$B$BZdobędziesz je na nietoperzach ze Wschodnich Plagowisk.', 0),
(7927, 'plPL', 'Widzę, że udało ci się skompletować talię portali! Gratulacje!', 0),
(7928, 'plPL', 'Widzę, że udało ci się skompletować talię wodzów! Gratulacje!', 0),
(7929, 'plPL', 'Widzę, że udało ci się skompletować talię żywiołaków! Gratulacje!', 0),
(7930, 'plPL', 'Zapraszam, zapraszam! Jeśli masz kupony Festynu Lunomroku, które chcesz wymienić, po prostu powiedz! Kupony w różnej liczbie wymienisz na cudowne i fantastyczne nagrody. Nie ma co się bać, trzeba brać!', 0),
(7931, 'plPL', 'Zapraszam, zapraszam! Jeśli masz kupony Festynu Lunomroku, które chcesz wymienić, po prostu powiedz! Kupony w różnej liczbie wymienisz na cudowne i fantastyczne nagrody. Nie ma co się bać, trzeba brać!', 0),
(7932, 'plPL', 'Zapraszam, zapraszam! Jeśli masz kupony Festynu Lunomroku, które chcesz wymienić, po prostu powiedz! Kupony w różnej liczbie wymienisz na cudowne i fantastyczne nagrody. Nie ma co się bać, trzeba brać!', 0),
(7933, 'plPL', 'Zapraszam, zapraszam! Jeśli masz kupony Festynu Lunomroku, które chcesz wymienić, po prostu powiedz! Kupony w różnej liczbie wymienisz na cudowne i fantastyczne nagrody. Nie ma co się bać, trzeba brać!', 0),
(7934, 'plPL', 'Zapraszam, zapraszam! Jeśli masz kupony Festynu Lunomroku, które chcesz wymienić, po prostu powiedz! Kupony w różnej liczbie wymienisz na cudowne i fantastyczne nagrody. Nie ma co się bać, trzeba brać!', 0),
(7935, 'plPL', 'Zapraszam, zapraszam! Jeśli masz kupony Festynu Lunomroku, które chcesz wymienić, po prostu powiedz! Kupony w różnej liczbie wymienisz na cudowne i fantastyczne nagrody. Nie ma co się bać, trzeba brać!', 0),
(7936, 'plPL', 'Zapraszam, zapraszam! Jeśli masz kupony Festynu Lunomroku, które chcesz wymienić, po prostu powiedz! Kupony w różnej liczbie wymienisz na cudowne i fantastyczne nagrody. Nie ma co się bać, trzeba brać!', 0),
(7937, 'plPL', 'Ten stóg siana wygląda jak ten z twojej wizji.', 0),
(7939, 'plPL', '$N, dziękuję za całą pomoc, jakiej mi $gudzieliłeś:udzieliłaś;. Naprawdę nie wiem, jak ci dziękować!$B$BChoć nie potrzebuję ich już tak bardzo... jeśli przyniesiesz mi więcej gęstych kamieni szlifierskich, wciąż mam dla ciebie kupony Festynu Lunomroku.', 0),
(7940, 'plPL', 'Zapraszam, zapraszam! Jeśli masz kupony Festynu Lunomroku, które chcesz wymienić, po prostu powiedz! Kupony w różnej liczbie wymienisz na cudowne i fantastyczne nagrody. Nie ma co się bać, trzeba brać!', 0),
(7941, 'plPL', '$N, muszę ci podziękować za całą pomoc. Zapasów mam pod dostatkiem, w niemałej mierze dzięki tobie, ale jeśli chcesz przynieść mi więcej zestawów pancernych, chętnie wymienię je na kupony Festynu Lunomroku.', 0),
(7942, 'plPL', '$N, tyle dobrego dla nas $gzrobiłeś:zrobiłaś;, niestrudzenie znosząc mi towary. Masz moją dozgonną wdzięczność!$B$BChoć nie potrzebujemy już ustrojstw z torium tak bardzo jak dawniej, nadal możesz mi je przynosić, a ja chętnie wymienię je na kupony Festynu Lunomroku.', 0),
(7943, 'plPL', '$N, atrakcja, którą projektuję, będzie najstraszniejszym wydarzeniem od czasu upadku Gnomoregan! A to w dużej mierze dzięki tobie i wszystkim błyskotkom, które mi $gprzyniosłeś:przyniosłaś;. Stokrotne dzięki!$B$BNiewiele mi już trzeba, ale... jeśli przyniesiesz mi więcej złych oczu nietoperzy ze Wschodnich Plagowisk... może znajdę dla ciebie jeszcze trochę kuponów Festynu Lunomroku.', 0),
(7946, 'plPL', 'Tak się cieszę, że Jubjub się znalazła. Tak bardzo kocha piwo Czarnorytych, że kiedy mi się skończyło... uciekła, żeby poszukać go więcej!$B$BTeraz, gdy Jubjub wróciła, chcę mieć tyle piwa, ile się da! Nie chcę, żeby znowu uciekła!$B$BMasz może piwo Czarnorytych? Jeśli tak, za kufel dam ci jedno z żabich jaj Jubjub...', 0),
(7981, 'plPL', 'Zapraszam, zapraszam! Jeśli masz kupony Festynu Lunomroku, które chcesz wymienić, po prostu powiedz! Kupony w różnej liczbie wymienisz na cudowne i fantastyczne nagrody. Nie ma co się bać, trzeba brać!', 0),
(8222, 'plPL', 'Przez cały czas pracy na Festynie sporo dowiedziałem się o klientach. Oto jedna z tych złotych myśli: klienci uwielbiają rzeczy, które świecą! Nieważne, co to jest – weź złamaną nogę od krzesła, spraw, by świeciła, a wszystkie dzieci z okolicy zlecą się po taką!$B$BDlatego, $N, potrzebuję lśniącej krwi skorpiady. Znajdziesz ją u skorpiad z Silithusu, Jałowych Ziem albo Płonących Stepów.', 0),
(8223, 'plPL', 'Ta krew skorpiady sprawdza się znakomicie, $N! To niesamowite, jak odrobina blasku i połysku potrafi zamienić zwykły rupieć w upragnione cacko. Goście to uwielbiają, a przecież o uwielbienie w tym wszystkim chodzi, nie sądzisz...$B$BBardzo mi $gpomogłeś:pomogłaś;, $N, i choć nie potrzebuję już tak bardzo lśniącej krwi skorpiady, to jeśli przyniesiesz mi jej więcej, nadal dam ci za nią kupony.', 0),
(8499, 'plPL', 'Och, przesyłka od mojego brata? Wspaniale! Szczęście naprawdę mi dziś sprzyja!', 0),
(9249, 'plPL', 'Zapraszam, zapraszam! Jeśli masz kupony Festynu Lunomroku, które chcesz wymienić, po prostu powiedz! Kupony w różnej liczbie wymienisz na cudowne i fantastyczne nagrody. Nie ma co się bać, trzeba brać!', 0),
(9278, 'plPL', 'Witaj! Miło cię poznać!$B$BWidzę, że masz specjalny bon. Daj mi go, a dam ci coś w zamian.', 0),
(10938, 'plPL', 'Widzę, że udało ci się skompletować talię błogosławieństw! Gratulacje!', 0),
(10939, 'plPL', 'Widzę, że udało ci się skompletować talię burz! Gratulacje!', 0),
(10940, 'plPL', 'Widzę, że udało ci się skompletować talię furii! Gratulacje!', 0),
(10941, 'plPL', 'Widzę, że udało ci się skompletować talię obłędu! Gratulacje!', 0),
(11131, 'plPL', '$N, $gobiecałeś:obiecałaś; uratować dzieci!', 0),
(11242, 'plPL', 'Masz coś dla mnie, $N?', 0),
(11360, 'plPL', 'Witaj, $N. Doskonalisz swoje techniki gaszenia pożarów? Nie zapomnij o placu ćwiczeń na północy!', 0),
(11439, 'plPL', 'Witaj, $n. Doskonalisz swoje techniki gaszenia pożarów? Nie zapomnij o placu ćwiczeń na południu!', 0),
(11440, 'plPL', 'Witaj, $n. Doskonalisz swoje techniki gaszenia pożarów? Nie zapomnij o placu ćwiczeń na zachodzie!', 0),
(11964, 'plPL', 'Ogniste pozdrowienia, $N. Witaj na uświęconej ziemi Festiwalu Ognia Letniego Przesilenia.', 0),
(12135, 'plPL', '$N, $gobiecałeś:obiecałaś; uratować dzieci!', 0),
(13324, 'plPL', 'Widzę, że udało ci się skompletować talię Pryzmatów! Gratulacje!', 0),
(13325, 'plPL', 'Widzę, że udało ci się skompletować talię Chaosu! Gratulacje!', 0),
(13326, 'plPL', 'Widzę, że udało ci się skompletować talię Szlachty! Gratulacje!', 0),
(13327, 'plPL', 'Widzę, że udało ci się skompletować talię Nieżycia! Gratulacje!', 0),
(13479, 'plPL', 'Masz fragmenty?', 0),
(13480, 'plPL', 'Masz fragmenty?', 0),
(13502, 'plPL', 'Masz dziesięć czekoladek z Miłogrodów?', 0),
(13503, 'plPL', 'Masz dziesięć czekoladek z Miłogrodów?', 0),
(13952, 'plPL', 'Nie masz przypadkiem chleba umarłych?', 0),
(14079, 'plPL', 'Ach, $gdostałeś:dostałaś; mój list? Dobrze.', 0),
