INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(234, 0, 'plPL', 'Plugawe zepsucie wkradło się do Zachodniego Skraju. Gdy pełniłem swój obowiązek na polach bitew Lordaeronu, te uczciwe farmy zostały opanowane i zamienione w kryjówki zbirów i morderców. Milicja Ludowa potrzebuje twojej pomocy.', 0),
(237, 0, 'plPL', 'Same kłopoty w tych stronach. Próbowałem przekonać tego głupca Saldeana, żeby się wynosił, póki może, ale nie chce o tym słyszeć. Ale ja nie jestem głupi. Razem z Verną zwijamy się stąd, jak tylko naprawimy ten wóz.', 0),
(240, 0, 'plPL', 'Ech, trudno tu utrzymać porządek i bez tych wszystkich nowych kłopotów, które wciąż wyskakują! Mam nadzieję, że masz dobre wieści, $n...', 0),
(241, 0, 'plPL', 'Witaj, $gprzyjacielu:przyjaciółko;. Nazywam się Remy. Jestem z Rudej Grani na wschodzie i przyjechałem tu szukać interesów, szukać interesów. Masz coś... masz coś??', 0),
(253, 0, 'plPL', 'Aha! Dzień dobry, dzień dobry! Chodź, usiądź i napij się. Masz w oku błysk przedsiębiorczości i myślę, że rozmowa ze mną będzie warta twojego czasu...', 0),
(261, 0, 'plPL', 'Witaj, $gobywatelu:obywatelko;. Wyglądasz na $gczłowieka:kobietę; z celem – masz jakąś sprawę do Armii Wichrogrodu?', 0),
(267, 0, 'plPL', 'Witaj w Mrocznych Włościach. Urzędnik Daltry do usług. Czy mogę w czymś pomóc?', 0),
(273, 0, 'plPL', 'Zamykaj drzwi. Nigdy nie wiadomo, kiedy znów przejadą tędy Mroczni Jeźdźcy.', 0),
(278, 0, 'plPL', 'Witaj, $gszanowny panie:szanowna pani;. Usiądź i zjedz coś, jeśli jesteś $ggłodny:głodna;. Nie przejmuj się, że wyglądam na zajętą robótką – słucham cię...', 0),
(294, 0, 'plPL', 'Witaj, wędrowcze. Może i mam słaby wzrok, ale kroki wojownika czy maga wyczuję z odległości mili. Przez lata z dumą broniłem Wichrogrodu, ale kiedy zawiodły mnie oczy, musiałem przejść na emeryturę.', 0),
(313, 0, 'plPL', 'Witaj w Wieży Azory. Jestem Theocritus.$B$BMasz do mnie jakąś sprawę? A może... to ja mam sprawę do ciebie?', 0),
(341, 0, 'plPL', 'Nie mam czasu na pogaduszki, $N. Muszę odbudować ten most, zanim przyjdą deszcze. Każdy projekt kończyłem na czas i poniżej budżetu i nie zamierzam teraz zacząć się spóźniać.', 0),
(415, 0, 'plPL', 'Hej, $gkolego:proszę pani;, możesz mi w czymś pomóc? Jestem w naprawdę PODŁYM położeniu...', 0),
(823, 0, 'plPL', 'Witaj. Normalnie chodziłbym po ulicach i pilnował mieszkańców Wichrogrodu, ale wielu strażników Wichrogrodu walczy w innych krainach. No i jestem tu, jako zastępca, wyznaczam nagrody, choć wolałbym być na patrolu...', 0),
(1440, 0, 'plPL', 'Nigdzie nie znajdziesz większej skarbnicy wiedzy niż w Bibliotece Królewskiej w Wichrogrodzie!', 0),
(6171, 0, 'plPL', 'Mrok, który otacza nasze ziemie, wiele razy wystawi cię na próbę, $N. Ale żebyś zawsze $gbył gotowy:była gotowa;, będziemy często zlecać ci zadania, dzięki którym będziesz w szczytowej formie.$B$BIdź ze Światłością i pozostań $gprawy:prawa;.', 0),
(6946, 0, 'plPL', 'Mathias znalazł mnie na Pustkowiach, gdzie spółka Gitgeszeft zostawiła mnie na pewną śmierć. Gdyby nie on, zostałbym karmą dla drapieżców.', 0);
