INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(39, 'plPL', 'Gdzie nie spojrzę, widzę złodziei. My, Milicja Ludowa, musimy zwrócić tę ziemię rolnikom.', '', 0),
(40, 'plPL', 'Farmy muszą zostać wyzwolone. Wichrogród mógł porzucić tych ludzi, ale niech mnie diabli, jeśli ja to zrobię.', '', 0),
(44, 'plPL', 'Mieszkańcy Zachodniego Skraju nie wybaczą Wichrogrodowi, że ich porzucił.', '', 0),
(50, 'plPL', 'No dalej, chłopaki, musimy odbudować ten most.', '', 0),
(56, 'plPL', 'Nie mogę uwierzyć, że ten przeklęty wóz się zepsuł. W tej krainie nie ma za grosz szczęścia. . . .', '', 0),
(57, 'plPL', 'Wyniesiemy się stąd, jak tylko naprawię ten wóz. . . .', '', 0),
(58, 'plPL', 'No i jak mam wygonić te mechaniczne paskudztwa z moich pól?', '', 0),
(59, 'plPL', 'Banda zbirów i złodziei nie zmusi mnie do opuszczenia mojej ziemi!', '', 0),
(60, 'plPL', 'Mogli przepędzić wszystkich innych rolników, ale Saldeanowie nigdy nie opuszczą Zachodniego Skraju.', '', 0),
(82, 'plPL', 'Ta mroczna skaza jest fatalna dla interesów.', '', 0),
(84, 'plPL', 'Oby twój kufel, gdy już pełny, napełnił się znowu!', '', 0),
(85, 'plPL', 'Witaj w karczmie „Lwia Duma”. Czuj się jak u siebie!', '', 0),
(86, 'plPL', 'Tyle do zrobienia, tyle do zrobienia! Gdzie ucieka ten czas?', '', 0),
(197, 'plPL', 'Chwała $n! $GObrońcy:Obrończyni; Ludu!', '', 0),
(198, 'plPL', 'Mieszkańcy Zachodniego Skraju oddają cześć – oto $n, $godważny i dzielny obrońca:odważna i dzielna obrończyni; wolności.', '', 0),
(199, 'plPL', 'Trzykrotne hura na cześć $n! Ta ziemia znów będzie nasza!', '', 0),
(282, 'plPL', 'Dziękuję ci, $n. Niech Światłość cię błogosławi, $Gbracie:siostro;, i prowadzi twoją ścieżką.', '', 0),
(683, 'plPL', '%s głęboko wzdycha.', '', 0),
(684, 'plPL', 'Nie znoszę tej części mojej pracy. Och, Knieja Zmierzchu, bądź łaskawa dla biednego Antonia.', '', 0),
(685, 'plPL', 'Starożytności, broń wojenna, rzadkie pancerze. Kto wie, co Antonio będzie miał w tym tygodniu, jeśli nie przyjdziecie zobaczyć?', '', 0),
(686, 'plPL', 'W tym tygodniu może to być oko traszki, a może mapa skarbów. Nie dowiecie się, dopóki nie zajrzycie. Co też może mieć Antonio?', '', 0),
(687, 'plPL', 'Poszukiwacze przygód z całego świata sprzedają rzeczy Antoniowi – przyjdźcie i sami zobaczcie, jakie skarby ma dla was w tym tygodniu.', '', 0),
(688, 'plPL', 'Podróżni i poszukiwacze przygód, spieszcie na rynek i skorzystajcie ze wspaniałych cen Antonia! Zapraszam wszystkich!', '', 0),
(689, 'plPL', 'Witajcie, podróżni Kniei Zmierzchu! Moje niezwykłe towary są przez krótki czas dostępne w Mrocznych Włościach. Pospieszcie się!', '', 0),
(690, 'plPL', 'Zostawcie swoje bitwy i sprawunki, i obejrzyjcie moje niezwykłe towary! Tylko przez krótki czas w Mrocznych Włościach... i chwała za to Światłości.', '', 0),
(691, 'plPL', 'Żegnajcie, mieszkańcy Mrocznych Włości. Do następnego razu...', '', 0),
(692, 'plPL', 'Nareszcie Ruda Grań. Miła odmiana po ciemnej, zimnej mgle Kniei Zmierzchu.', '', 0),
(702, 'plPL', 'Witaj, witaj, Amy. Dobrze znów być w Jeziernych Włościach i widzieć panią.', '', 0),
(704, 'plPL', 'Słuchajcie, słuchajcie! Zatrzymam się tu, w Jeziernych Włościach, tylko na krótko, by sprzedać swoje towary. Spieszcie do ratusza!', '', 0),
(712, 'plPL', 'Nareszcie dotarłem do Jeziernych Włości – przyjdźcie wszyscy i skorzystajcie ze wspaniałych okazji Antonia Perellego.', '', 0),
(713, 'plPL', 'Przedmioty dość potężne, by pomóc w przeprawie przez Knieję Zmierzchu – towary Antonia Perellego są teraz na sprzedaż tu, w Jeziernych Włościach.', '', 0),
(714, 'plPL', 'Miło było znów cię zobaczyć, Amy. Uważaj na siebie, kochana. Ruszam teraz do Złotych Włości.', '', 0),
(716, 'plPL', 'Witajcie, przyjaciele. Dobrze was znów widzieć. Widzę, że wciąż strzeżecie naszych granic. Antonio docenia waszą ciężką pracę.', '', 0),
(717, 'plPL', 'Nie ma za co! Muszę ruszać w drogę... uważajcie na siebie, wszyscy.', '', 0),
(718, 'plPL', 'Witaj znowu, Antonio. Jeszcze raz dziękuję za kapelusz dla mojej żony. Była nim zachwycona.', 'Witaj znowu, Antonio. Jeszcze raz dziękuję za kapelusz dla mojej żony. Była nim zachwycona.', 0),
(719, 'plPL', 'Uważaj na siebie, Antonio.', 'Uważaj na siebie, Antonio.', 0),
(720, 'plPL', 'Och, będę, przyjacielu. Z pewnością będę. Ty też uważaj na siebie.', '', 0),
(721, 'plPL', 'Towary na sprzedaż! Towary na sprzedaż! Obejrzyjcie towary Antonia, zanim będę musiał odjechać, mieszkańcy Złotych Włości.', '', 0),
(722, 'plPL', 'Zapraszam wszystkich! Towary Antonia na sprzedaż. Mogę długo nie wrócić, więc zapraszam wszystkich!', '', 0),
(723, 'plPL', 'Dobrzy ludzie ze Złotych Włości, skorzystajcie z moich niezwykłych cen na rzadkie towary. Przez jakiś czas nie wrócę!', '', 0),
(724, 'plPL', 'Do widzenia, Złote Włości. Wrócę niedługo – może za tydzień.', '', 0),
(726, 'plPL', 'Znane w całej krainie towary Antonia Perellego są teraz na sprzedaż przy Wzgórzu Strażniczym! Wkrótce muszę ruszać dalej, więc się pospieszcie.', '', 0),
(727, 'plPL', 'Trwałe, solidnie wykonane przedmioty na sprzedaż przy Wzgórzu! Zapraszam wszystkich! Czasu jest mało, więc się pospieszcie.', '', 0),
(728, 'plPL', 'Nadszedł czas, bym znów udostępnił swoje towary wszystkim, którzy podróżują w pobliżu Wzgórza Strażniczego! Zapraszam wszystkich!', '', 0),
(729, 'plPL', 'Dziękuję wam wszystkim. Wrócę za mniej więcej tydzień.', '', 0),
(730, 'plPL', 'No to chyba do Mrocznych Włości.', '', 0),
(893, 'plPL', 'Rety, ryby tu wcale nie biorą. Może pójdę nad Kryształowe Jezioro spróbować szczęścia!', '', 0),
(894, 'plPL', 'Kurczę! Tu też nie biorą. Wracam do mojego starego łowiska!', '', 0),
(1101, 'plPL', 'Świeży chleb na sprzedaż!', '', 0),
(1242, 'plPL', 'Możesz odejść, $n.', '', 0),
(1851, 'plPL', 'To nie powinno długo potrwać...', '', 0),
(1853, 'plPL', 'Trunek niewidzialności jest gotowy, $n.', '', 0),
(1862, 'plPL', '', 'Raz kozie śmierć...', 0),
(1863, 'plPL', 'Nie zabijać mnie! Nie zabijać mnie!', '', 0),
(1864, 'plPL', 'Jiiiiii! Ja uciekać!', '', 0),
(1865, 'plPL', 'Ach, okazja, by użyć świeżo naostrzonego ostrza.', 'Ach, okazja, by użyć świeżo naostrzonego ostrza.', 0),
(1866, 'plPL', 'Bractwo nie będzie tolerować twoich poczynań.', 'Bractwo nie będzie tolerować twoich poczynań.', 0),
(1867, 'plPL', 'Poczuj potęgę Bractwa!', 'Poczuj potęgę Bractwa!', 0),
(1868, 'plPL', 'Ty nie brać świeczka!', '', 0),
(1870, 'plPL', 'Grrrr... świeże mięso!', '', 0),
(1871, 'plPL', 'Więcej kości do ogryzania...', '', 0),
(2283, 'plPL', 'Dziękuję ci, $gchłopcze:dziewczyno;. Wielkie dzięki.', '', 0),
(2284, 'plPL', 'Dzięki tobie, $n.', '', 0),
(2303, 'plPL', '%s zabiera się do pracy...', '', 0),
(2341, 'plPL', '%s zabiera się do pracy...', '', 0),
